window.SDT_TERMS={"b":[{"ko":"발주자","en":"client, owner","say":"공사를 주문하고 도급하는 사람, 계약상 갑","more":"건축주 또는 시행자라고도 함. 개인, 법인, 공공단체, 정부기관."},{"ko":"시공자","en":"builder, contractor","say":"공사의 제반 업무를 책임지고 시행하는 사람, 공사관리자","more":"도급자라고도 함. 회사에 의뢰하면 시공사."},{"ko":"감리자","en":"construction supervisor","say":"설계도서대로 시공되는지 확인하고 지도, 감독하는 사람","more":"인테리어 디자인은 의무 감리제도가 없지만 품질관리를 위해 시행."},{"ko":"가설공사","en":"","say":"본 공사를 위해 임시로 설치했다가 끝나면 철거하는 공사","more":"설계도에 일반적으로 표시되지 않고 시방서에 간단한 지시만. 현장소장 책임."},{"ko":"철거공사","en":"","say":"새 인테리어 전에 기존 시설과 마감재를 걷어내는 공사","more":"실내는 인력에 의한 철거가 보편적. 폭발력 철거는 거의 안 씀."},{"ko":"도급","en":"","say":"한쪽이 일을 완성하고 상대가 그 결과에 보수를 주기로 한 계약","more":"민법 664조에 정의."},{"ko":"원도급자","en":"","say":"발주자와 직접 공사계약을 한 시공업자"},{"ko":"하도급자","en":"","say":"원도급자에게서 공사 일부를 직종별로 다시 맡은 전문업자","more":"협력업체."},{"ko":"현장소장","en":"","say":"현장을 총괄해 공정, 품질, 안전, 원가, 현장운영을 관리하는 책임자","more":"설계변경은 임의로 하지 않고 발주처, 설계자와 협의."},{"ko":"직영공사","en":"","say":"발주자가 재료, 노무자, 장비를 직접 마련해 관리하는 방식","more":"공사비 절감 가능. 전문지식이 부족하면 완성도 저하, 공사비 증가, 공기 연장. 셀프 인테리어."},{"ko":"일식도급","en":"","say":"공사 전부를 한 도급자에게 일괄로 맡기는 방식","more":"총괄도급. 가장 일반적, 설계는 포함 아님. 공사비 확정, 책임 명료."},{"ko":"정액도급","en":"","say":"공사비 총액을 확정해 계약하는 방식","more":"공사관리가 간편. 설계변경이 많거나 장기 공사에는 부적당."},{"ko":"단가도급","en":"","say":"단위 단가만 정하고 실제 시공 수량으로 정산하는 방식","more":"빠른 착공 가능. 예: 1㎡당 50,000원 × 120㎡."},{"ko":"턴키","en":"Turn-key","say":"모든 것을 조달해 바로 쓸 수 있는 상태로 인도하는 도급 방식","more":"일반적으로 설계와 시공을 함께 발주하는 일괄 입찰의 뜻."},{"ko":"공개경쟁입찰","en":"open competitive bidding","say":"조건을 모두 공개해 유자격자 누구나 참가하게 하는 입찰","more":"투명하지만 과도한 경쟁, 부적격 업체로 부실공사 우려."},{"ko":"수의계약","en":"optional contract","say":"적합하다고 판단한 하나의 업체를 지정해 계약하는 방식","more":"개인 발주자는 제한 없음, 공공기관은 일정 금액 이하만."},{"ko":"직접공사비","en":"","say":"재료비, 노무비, 외주비, 경비처럼 공사에 직접 쓴 비용"},{"ko":"순공사비","en":"","say":"직접공사비에 공통 가설비와 간접공사비를 더한 금액","more":"원가 순서: 직접공사비, 순공사비, 공사원가, 총원가, 계약금액."},{"ko":"공사원가","en":"","say":"순공사비에 현장경비를 더한 금액"},{"ko":"총원가","en":"","say":"공사원가에 일반관리비를 더한 금액","more":"총원가에 이윤과 부가가치세를 더하면 계약금액."},{"ko":"일반관리비","en":"","say":"본사를 유지하는 데 드는 비용","more":"현장에 들어가는 돈이 아니라 본사 인원 등 기업 경영을 위한 돈이에요. 공사원가에 더하면 총원가예요."},{"ko":"계약금액","en":"","say":"발주자가 실제로 내기로 한 최종 공사 금액","more":"총원가에 부가이윤 및 부가가치세를 더한 금액이에요. 공사비라고도 해요."},{"ko":"공정계획","en":"process planning","say":"착공부터 준공까지 기간 내 좋은 품질로 안전하게 진행하도록 짜는 계획","more":"요소: 시기, 내용, 수량, 인력. 수단: 인력, 장비, 자금, 자원."},{"ko":"네트워크 공정표","en":"Network","say":"작업의 시작, 완료와 연계를 원과 화살표로 표시하는 공정표","more":"전체 파악과 상호 관계가 명확. 작성에 시간과 전문성이 필요."},{"ko":"바차트 공정표","en":"Bar chart","say":"공종을 세로에 쓰고 기간을 가로 막대로 표시하는 공정표","more":"횡선식, 막대공정표. 착수일과 완료일 판단이 쉽지만 상호관계 확인이 어려움. 실제 현장에서 더 많이 씀."},{"ko":"주공정선","en":"Critical Path","say":"가장 긴 경로, 지연되면 전체 공사가 늦어지는 작업 경로","more":"예시: 철거 2일, 전기 3일, 마감 3일, 도장 2일 = 10일."},{"ko":"여유시간","en":"Float","say":"전체 준공일에 영향 없이 늦어져도 되는 시간","more":"Slack이라고도 함."},{"ko":"평면도","en":"Floor Plan","say":"공간을 위에서 내려다본 모습으로 그린 도면","more":"방의 배치와 가로, 세로 길이, 문과 창의 위치를 읽어요. 실측도 평면도부터 시작해요."},{"ko":"입면도","en":"Elevation","say":"벽 한 면을 정면에서 바라본 모습으로 그린 도면","more":"천장고, 창과 문의 높이처럼 높이에 관한 것을 읽어요. 방마다 네 면을 그려요."},{"ko":"단면도","en":"Section","say":"건물이나 벽을 잘라 낸 것처럼 그려 속을 보여 주는 도면","more":"석고보드가 몇 겹인지, 스터드와 단열재가 어디에 있는지가 여기서 보여요."},{"ko":"천장도","en":"Ceiling Plan","say":"천장을 그려 조명과 점검구의 자리를 보여 주는 도면","more":"실측 순서는 평면도, 입면도, 천장도예요. 조명 중심 간격과 냉난방기 자리를 재요."},{"ko":"상세도","en":"","say":"특정 부위를 어떤 재료와 치수, 순서로 시공할지 보여 주는 도면","more":"상세도를 그린다 = 디테일을 푼다."},{"ko":"해칭","en":"Hatching","say":"잘린 재료의 속을 빗금이나 무늬로 칠해 표시하는 것","more":"단면도와 상세도에서 콘크리트, 석고보드, 단열재를 서로 다른 무늬로 구별해요."},{"ko":"범례","en":"Legend","say":"도면에 쓴 기호와 선이 무슨 뜻인지 모아 적은 표","more":"범례를 먼저 읽어야 도면의 기호가 읽혀요. 실측할 때는 벽, 전기, 수도를 색으로 나누기도 해요."},{"ko":"축척","en":"Scale","say":"도면에 그린 길이와 실제 길이의 비율","more":"1/50 이면 실제를 50분의 1로 줄여 그린 것이라, 도면 길이에 50 을 곱하면 실제 길이가 돼요."},{"ko":"밀리미터","en":"mm","say":"1m 의 1000분의 1 인 길이 단위","more":"실내 도면과 실측은 모두 mm 로 적어요. 1,200 이라고 적혀 있으면 1,200mm, 곧 1.2m 예요."},{"ko":"치수선","en":"Dimension Line","say":"두 점 사이의 길이를 화살표와 숫자로 나타낸 가는 선","more":"재는 곳에서 끌어낸 치수보조선 사이에 긋고, 숫자는 mm 로 적어요."},{"ko":"실측","en":"","say":"현장에 가서 줄자로 실제 치수를 재는 일","more":"전체 스케치, 평면도, 입면도, 천장도 순으로 재고 단위는 mm 로 적어요."},{"ko":"먹매김","en":"","say":"설계도서 치수대로 현장에 1:1로 도면을 옮겨 그리는 작업","more":"설계자, 현장소장, 목수가 참여. 설계자는 먹도면을 준비."},{"ko":"보양","en":"","say":"기존 시설이나 완성된 마감재의 파손, 오염을 막는 임시 보호","more":"바닥 타일, 석재 위에는 합판, 도장 때 벽에는 비닐, 코너와 문틀에는 각대."},{"ko":"비계","en":"","say":"높은 곳의 작업을 위해 설치하는 임시시설물","more":"종류: 강관(단관)비계, 시스템비계, 조립식(이동틀)비계, 말비계."},{"ko":"경량철골","en":"","say":"목재 대신 철재로 벽틀과 천장틀을 짜는 소재 또는 제품","more":"장점: 불연, 자중 감소, 공기 단축, 내화와 차음 성능 구현, 설비 설치 간단."},{"ko":"건식벽체","en":"Dry-Wall","say":"스터드 골조와 석고보드로 구성한 벽체","more":"기본 구성: 스터드 + 흡음충진재 + 석고보드 + 마감재."}],"2":[{"ko":"시공","en":"","say":"재료와 제품으로 사람이 쓸 공간을 실제로 만들어 내는 일","more":"기능, 구조, 미를 갖춘 공간을 최적의 비용으로 정해진 시간 안에 만드는 기술적, 경제적 활동과정."},{"ko":"발주자","en":"client, owner","say":"공사를 주문하고 도급하는 사람, 계약상 갑","more":"건축주 또는 시행자라고도 함. 개인, 법인, 공공단체, 정부기관."},{"ko":"설계자","en":"designer","say":"설계 도서를 만들고 그 디자인을 해설하며 지도, 자문하는 사람이나 회사","more":"기술력과 창의력을 바탕으로 설계도서를 작성해요."},{"ko":"감리자","en":"construction supervisor","say":"설계도서대로 시공되는지 확인하고 지도, 감독하는 사람","more":"인테리어 디자인은 의무 감리제도가 없지만 품질관리를 위해 시행."},{"ko":"시공자","en":"builder, contractor","say":"공사의 제반 업무를 책임지고 시행하는 사람, 공사관리자","more":"도급자라고도 함. 회사에 의뢰하면 시공사."},{"ko":"원도급자","en":"","say":"발주자와 직접 공사계약을 한 시공업자"},{"ko":"하도급자","en":"","say":"원도급자에게서 공사 일부를 직종별로 다시 맡은 전문업자","more":"협력업체."},{"ko":"노무자","en":"labor, worker","say":"현장에서 지시에 따라 노동을 하고 그 일에 대한 보수를 받는 사람","more":"직종별로 기능공, 조력공, 견습공, 조력인부. 고용 형태는 직용, 정용, 임시고용."},{"ko":"직용 노무자","en":"","say":"원도급자가 직접 고용한 노무자, 잡역 등 미숙련이 많음","more":"예: 현장 정리, 자재 운반, 청소."},{"ko":"정용 노무자","en":"","say":"전문업자나 하도급업자에게 계속 소속된 숙련 기능 노무자","more":"출역일수(현장에 출근한 일수)에 따라 임금. 목공, 미장공, 타일공 등."},{"ko":"임시고용 노무자","en":"","say":"필요한 기간에만 일시적으로 고용되는 노무자","more":"날품, 일용 형태가 많고 단순 작업이나 기능공 보조를 담당."},{"ko":"직영공사","en":"","say":"발주자가 재료, 노무자, 장비를 직접 마련해 관리하는 방식","more":"공사비 절감 가능. 전문지식이 부족하면 완성도 저하, 공사비 증가, 공기 연장. 셀프 인테리어."},{"ko":"도급","en":"","say":"한쪽이 일을 완성하고 상대가 그 결과에 보수를 주기로 한 계약","more":"민법 664조에 정의."},{"ko":"일식도급","en":"","say":"공사 전부를 한 도급자에게 일괄로 맡기는 방식","more":"총괄도급. 가장 일반적, 설계는 포함 아님. 공사비 확정, 책임 명료."},{"ko":"분할도급","en":"","say":"공사를 유형별로 세분해 각기 다른 도급자와 계약하는 방식","more":"공종별, 공정별, 공구별로 나눔."},{"ko":"공종별 도급","en":"","say":"금속, 목공, 전기처럼 공사 종류별로 나눠 전문업자와 계약하는 방식","more":"가장 기본적인 분할도급. 공사 관리가 복잡하고 가설, 기계 설치가 중복될 수 있음."},{"ko":"공정별 도급","en":"","say":"골조와 마감처럼 공사 과정별로 나눠 맡기는 방식","more":"후속공사 업자가 바뀌면 연계가 원활하지 않을 수 있음."},{"ko":"공구별 도급","en":"","say":"대규모 면적의 공사를 지역별로 나눠 맡기는 방식","more":"기술 수준이 유사한 다수 업체와 계약해 경쟁 유도, 공사기일 단축, 시공기술 향상을 기대."},{"ko":"공동도급","en":"","say":"여러 회사가 공동출자해 한 회사처럼 공사를 수급하는 방식","more":"대규모 아파트 공사. 자금 부담과 위험 분담."},{"ko":"공동이행방식","en":"","say":"같은 업종 업체들이 출자비율에 따라 공사 전체를 함께 수행하는 방식","more":"예: 래미안 + 푸르지오."},{"ko":"분담이행방식","en":"","say":"다른 업종 업체들이 공사 내용을 나눠 참여하는 방식","more":"예: 실내건축공사 A업체 + 기계설비공사 B업체. 슬라이드에는 '분담이해방식'으로 잘못 표기."},{"ko":"의무공동도급","en":"","say":"지방자치단체 공사에 그 지역 업체를 반드시 끼워 넣게 하는 공동도급","more":"지역 건설업체 수주 기회 확대와 지역경제 활성화 목적. 자격 업체가 10개 미만이면 적용하지 않을 수 있음."},{"ko":"정액도급","en":"","say":"공사비 총액을 확정해 계약하는 방식","more":"공사관리가 간편. 설계변경이 많거나 장기 공사에는 부적당."},{"ko":"단가도급","en":"","say":"단위 단가만 정하고 실제 시공 수량으로 정산하는 방식","more":"빠른 착공 가능. 예: 1제곱미터당 50,000원 곱하기 120제곱미터."},{"ko":"실비정산보수가산도급","en":"","say":"실제 공사비를 정산하고 약정한 보수를 더해 주는 방식","more":"덤핑에 따른 부실공사 방지. 대신 공사비 절감 노력이 없어질 수 있음."},{"ko":"턴키","en":"Turn-key","say":"모든 것을 조달해 바로 쓸 수 있는 상태로 인도하는 도급 방식","more":"일반적으로 설계와 시공을 함께 발주하는 일괄 입찰의 뜻."},{"ko":"공개경쟁입찰","en":"open competitive bidding","say":"조건을 모두 공개해 유자격자 누구나 참가하게 하는 입찰","more":"투명하지만 과도한 경쟁, 부적격 업체로 부실공사 우려."},{"ko":"제한경쟁입찰","en":"private competitive bidding","say":"실적, 기술, 재무 등으로 참가 업체 범위를 제한하는 입찰"},{"ko":"지명경쟁입찰","en":"selective bidding","say":"특수 기술 등이 필요할 때 특정 다수 업체를 지명해 참가시키는 입찰","more":"담합의 우려."},{"ko":"수의계약","en":"optional contract","say":"적합하다고 판단한 하나의 업체를 지정해 계약하는 방식","more":"개인 발주자는 제한 없음, 공공기관은 일정 금액 이하만."},{"ko":"입찰보증금","en":"bid bond","say":"낙찰 후 계약 체결을 담보하려고 내는 보증금","more":"입찰금액의 5% 이상. 정당한 사유 없이 계약하지 않으면 국가나 지자체에 귀속."},{"ko":"입찰참가자격 사전심사","en":"PQ","say":"입찰 전에 공사수행능력을 미리 심사해 참가 자격을 주는 제도","more":"Prequalification. 신규, 중소업체에는 진입장벽이 될 수 있음."},{"ko":"현장설명","en":"on-site orientation","say":"설계도서에 나타낼 수 없는 사항을 현지에서 보충 설명하는 것","more":"종종 실측, 사진 촬영 가능."},{"ko":"총액입찰","en":"","say":"세부내역 없이 공사 전체 총액만 적어 내는 입찰","more":"추정가격 100억 원 미만."},{"ko":"내역입찰","en":"","say":"공종별 단가를 적은 산출내역서를 입찰서와 함께 내는 입찰","more":"관급공사에서 추정가격 100억 원 이상."},{"ko":"유찰","en":"","say":"입찰이 성립하지 않거나 낙찰자가 결정되지 않은 것"},{"ko":"재입찰","en":"rebidding","say":"기존 입찰조건을 유지한 채 다시 투찰하게 하는 것","more":"새로운 입찰로 보지 않으며 횟수 제한이 없음."},{"ko":"재공고입찰","en":"","say":"입찰공고부터 다시 해서 절차를 새로 진행하는 것","more":"재공고입찰에서도 낙찰자가 없으면 관계 법령에 따라 수의계약을 체결할 수 있음."},{"ko":"계약","en":"contract","say":"서로 지켜야 할 의무를 정하는 것","more":"인테리어에서는 설계와 시공을 위하여 발주자와 도급자 사이에 체결되는 약정. 체결되면 쌍방의 관계가 법률적으로 확정."},{"ko":"계약서","en":"contract document","say":"발주자와 도급자의 의무와 권리를 담은 약정서","more":"분쟁 시 계약서, 설계도서, 견적서, 특약사항을 기준으로 책임과 이행 범위를 판단."},{"ko":"수급인","en":"","say":"건설공사 도급계약에서 공사를 수행하는 쪽","more":"공사를 맡기는 쪽은 발주자(도급인)라고 해요."},{"ko":"간인","en":"","say":"위, 변조를 막으려고 계약서 장과 장 사이에 걸쳐 찍는 도장","more":"법적 의무가 아니며 없어도 계약 효력에는 영향 없음."},{"ko":"하자담보책임기간","en":"","say":"공사 후 생긴 하자를 보수할 책임이 있는 기간","more":"일반 실내건축공사 1년, 신축 공동주택 사업주체 마감공사 2년."},{"ko":"대수선","en":"","say":"내력벽 30제곱미터 이상이나 기둥, 보 3개 이상 수선처럼 허가, 신고가 필요한 공사","more":"건축법 시행령 제3조의2. 증축, 개축, 재축에 해당하지 않는 것."},{"ko":"건축물대장","en":"","say":"건축물의 용도 등을 적어 둔 공적 장부","more":"정부24 또는 세움터에서 온라인 발급, 열람 가능. 관공서에서 직접 발급도 가능."},{"ko":"사용승인","en":"","say":"공사를 끝낸 건축물을 써도 좋다고 허가권자가 확인해 주는 절차","more":"원칙적으로 사용승인을 받기 전에는 건축물을 사용할 수 없어요."},{"ko":"실행내역서","en":"","say":"계약금액 중 실제 공사에 투입할 예산을 정리한 대외비 문서","more":"계약금액에서 일반관리비와 이윤을 뺀 공사원가에 해당."},{"ko":"직접공사비","en":"","say":"재료비, 노무비, 외주비, 경비처럼 공사에 직접 쓴 비용","more":"공사 목적물을 시공하기 위해 직접 소비된 것을 확인할 수 있는 비용."},{"ko":"공통 가설비","en":"","say":"현장 가설사무실, 보양, 안전시설처럼 공사 전체를 위해 드는 임시 비용"},{"ko":"간접공사비","en":"","say":"여러 시공 부분이 공통으로 쓰며 비율로 계산하는 비용","more":"현장관리 인건비, 운반비, 전력, 용수비 등."},{"ko":"순공사비","en":"","say":"직접공사비에 공통 가설비와 간접공사비를 더한 금액","more":"원가 순서: 직접공사비, 순공사비, 공사원가, 총원가, 계약금액."},{"ko":"현장경비","en":"","say":"현장 시공 관리를 위해 쓰는 인건비와 기타 경비","more":"현장관리 인력의 인건비, 통신비, 여비교통비 등. 숙소, 식사, 직원 유류비."},{"ko":"공사원가","en":"","say":"순공사비에 현장경비를 더한 금액"},{"ko":"일반관리비","en":"","say":"현장 밖에서 회사를 유지하는 데 드는 돈","more":"본사 인원 인건비 등 시공업체의 기업 경영을 유지하기 위하여 지출하는 금액."},{"ko":"총원가","en":"","say":"공사원가에 일반관리비를 더한 금액","more":"총원가에 부가이윤과 부가가치세를 더하면 공사비, 즉 계약금액."},{"ko":"공정계획","en":"","say":"착공부터 준공까지 기간 내 좋은 품질로 안전하게 진행하도록 짜는 계획","more":"요소: 시기, 내용, 수량, 인력. 수단: 인력, 장비, 자금, 자원."},{"ko":"네트워크 공정표","en":"","say":"작업의 시작, 완료와 연계를 원과 화살표로 표시하는 공정표","more":"전체 파악과 상호 관계가 명확. 작성에 시간과 전문성이 필요."},{"ko":"바차트 공정표","en":"Bar chart","say":"공종을 세로에 쓰고 기간을 가로 막대로 표시하는 공정표","more":"횡선식, 막대공정표. 착수일과 완료일 판단이 쉽지만 상호관계 확인이 어려움. 실제 현장에서 더 많이 씀."},{"ko":"주공정선","en":"Critical Path","say":"가장 긴 경로, 지연되면 전체 공사가 늦어지는 작업 경로","more":"예시: 철거 2일, 전기 3일, 마감 3일, 도장 2일 = 10일."},{"ko":"여유시간","en":"Float","say":"전체 준공일에 영향 없이 늦어져도 되는 시간","more":"Slack이라고도 함."},{"ko":"시공관리","en":"","say":"신속, 우수, 안전, 경제라는 목적을 이루려고 공사를 관리하는 일","more":"신속하게(공정관리), 우수하게(품질관리), 안전하게(안전관리), 경제적으로(원가관리)."},{"ko":"착공","en":"","say":"공사에 착수하여 실제 시공을 시작하는 것","more":"착공일이 명시되지 않아도 일반적으로 5일 이내에 착공해야 해요."},{"ko":"착공계","en":"","say":"언제 공사를 시작해 언제 끝낼지 신고하는 착공서류","more":"착공신고서. 현장대리인 지정신고서, 예정공정표 등과 함께 제출."},{"ko":"현장대리인","en":"","say":"현장에서 시공사를 대표하는 기술자, 공사 담당자","more":"현장기술자라고도 하며 지정신고서와 자격, 경력 증빙서류를 함께 냅니다."},{"ko":"예정공정표","en":"","say":"며칠에 무엇을 할지 미리 적어 내는 공정표","more":"착공서류의 하나. 현장관리자는 이 표에 준하여 공사 진척을 관리해요."},{"ko":"산출내역서","en":"","say":"계약금액이 어떤 공종, 수량, 단가로 짜였는지 적은 서류","more":"총액입찰 낙찰자는 착공신고서를 낼 때 제출해요. 발주처와 시공자가 서로 확정하려고 만들어요."},{"ko":"직접시공계획서","en":"","say":"어느 부분을 자기 회사가 직접 시공할지 밝히는 서류","more":"공사를 전부 하도급으로 넘기지 않는다는 것을 발주자에게 알리는 법정 서류."},{"ko":"현장소장","en":"","say":"현장을 총괄해 공정, 품질, 안전, 원가, 현장운영을 관리하는 책임자","more":"현장관리자 또는 현장책임자라고도 해요. 설계변경은 임의로 하지 않고 발주처, 설계자와 협의."},{"ko":"공정관리","en":"","say":"정해진 공사기간에 맞게 공사 진척을 관리하는 일","more":"예정공정표에 따라 관리하고 공정별 작업내용과 작업순서를 조정하며 작업지시를 해요."},{"ko":"품질관리","en":"QC","say":"공사의 질적 향상을 목적으로 기준에 맞게 시공되는지 관리하는 일","more":"KS 기준과 건축 기본법에 명시된 바에 따라 품질의 향상과 기준의 확립을 위하여 관리."},{"ko":"안전관리","en":"","say":"사고와 재해를 미리 막으려고 필요한 사항을 정하고 관리하는 일","more":"공사 전, 공사 중, 공사 후 안전사고 예방이 주목적. 공사의 종류와 금액에 따라 적용기준이 달라요."},{"ko":"원가관리","en":"","say":"최소의 비용으로 최대의 효과를 내도록 공사비를 관리하는 일","more":"공사비 지불청구서, 자재 납품업체, 각종 공과금 등 현장 예산의 심사와 승인."},{"ko":"현장운영관리","en":"","say":"인력 배치와 근태, 자재와 장비의 반입과 보관을 챙기는 일","more":"공사 중 발생하는 문제를 파악하고 발주처, 설계자, 협력업체와 조정해요."},{"ko":"공사 작업일지","en":"","say":"그날의 작업 내용, 인력, 장비, 자재를 적어 남기는 기록","more":"공사일보라고도 해요. 금일 작업내용과 명일 작업내용, 출력현황을 적어요."},{"ko":"안전사고","en":"","say":"공사 현장에서 사람이 다치거나 물건이 망가지는 사고","more":"근로자의 부주의에 의해 발생하는 비율이 매우 높아요."},{"ko":"안전점검","en":"","say":"작업 중 안전사고를 막으려고 현장을 살펴보는 일","more":"일상점검, 정기점검, 수시점검으로 분류하여 실시."},{"ko":"화재예방","en":"","say":"불이 나지 않게 미리 막는 일","more":"근로자에게 주기적으로 소방교육 및 비상훈련을 실시해 대응 체제를 갖춰요."},{"ko":"소방안전관리감독자","en":"","say":"용접처럼 불꽃이 튀는 작업을 할 때 따로 지정하는 감독자","more":"용접은 페인트 도장, 우레탄 발포 등과 병행하지 않도록 공정을 조정해요."},{"ko":"가설울타리","en":"","say":"공사현장 주위를 둘러막는 임시 울타리","more":"건축법 규정에 따라 설치. 가설칸막이, 낙하물 방지망과 함께 설치해요."},{"ko":"가설칸막이","en":"","say":"공사 구역과 사용 중인 구역을 갈라 주는 임시 칸막이"},{"ko":"안전펜스","en":"","say":"공사 관계자 외의 접근을 막고 작업 영역을 표시하는 울타리","more":"스틸과 플라스틱 재질. 고정식과 이동식이 있어요."},{"ko":"바리케이트","en":"","say":"길이나 출입구를 막아 세우는 이동식 차단물","more":"안전펜스와 함께 쓰며 고정식과 이동식이 있어요. 입간판, 칼라콘도 같은 쓰임이에요."},{"ko":"낙하물 방지망","en":"","say":"위에서 떨어지는 물건을 받아 주는 그물","more":"건물의 내외부에 설치. 실내에서는 아트리움 같은 개구부에도 설치. 항상 규격품을 사용."},{"ko":"추락 방호망","en":"","say":"사람이 떨어질 때 받아 주는 그물","more":"높이 위치한 작업장에서 작업할 때 설치하는 시설."},{"ko":"안전표시","en":"","say":"위험을 알리고 주의를 환기시키려고 붙이는 포스터, 스티커, 휘장","more":"무재해, 안전사고 예방, 현장 정리 정돈 같은 표어나 구호로 구성."},{"ko":"안전모","en":"","say":"낙하물과 추락으로부터 머리를 보호하는 안전장구","more":"현장 내에서 작업하는 모든 작업자가 반드시 착용해야 해요."},{"ko":"안전 조끼","en":"","say":"어두운 작업복 위에 입어 작업자를 눈에 잘 띄게 하는 조끼","more":"작업자의 명시성을 높여 안전을 확보해요."},{"ko":"안전대","en":"","say":"높은 곳에서 안전줄에 걸어 추락을 막는 필수 장구","more":"안전모와 함께 반드시 착용. 상체식과 전체식(그네식)이 있어요."},{"ko":"안전화","en":"","say":"못이나 무거운 물건에서 발을 지켜 주는 현장 작업용 신발","more":"밑창에 내답판, 앞코에 선심이 들어 있어 발바닥과 발가락을 보호해요."},{"ko":"방진 마스크","en":"","say":"분진과 유독성 가스를 걸러 주는 마스크","more":"철거작업, 도장작업처럼 분진이 많이 나는 공정에서 반드시 착용. 필터가 붙은 제품과 일반 마스크 제품이 있어요."},{"ko":"보호면","en":"","say":"용접, 절단, 그라인딩 때 눈을 지켜 주는 얼굴 가리개","more":"불꽃, 분진, 파편으로부터 눈을 보호해요."},{"ko":"각반","en":"","say":"바짓단이 걸리거나 끼이는 사고를 막으려고 발목에 두르는 장구","more":"용접용 각반은 불티가 바지 속으로 들어가는 것도 막아 줘요."},{"ko":"안전관리업무일지","en":"","say":"현장의 안전관리 업무를 날짜별로 적어 두는 문서","more":"당일 재해 방지 중점 사항, 안전활동 세부 내용, 안전점검 결과, 재해사고 발생 현황을 적어요."},{"ko":"전수검사","en":"","say":"제품을 하나도 빼지 않고 모두 검사하는 방법"},{"ko":"발췌검사","en":"","say":"제품 중 일부 샘플만 뽑아서 검사하는 방법"},{"ko":"자재관리","en":"","say":"기자재와 공사 목적물을 상하지 않게 보존, 관리하는 일","more":"품질관리의 일환. 취급방법, 보관 장소와 방법, 시공된 목적물의 품질보호, 화재와 보안관리를 포함해요."},{"ko":"대운반","en":"","say":"트럭으로 자재를 배달받거나 폐자재를 반출하는 작업"},{"ko":"소운반","en":"","say":"수평거리 20m 이내에서 인력이나 간단한 도구로 자재를 옮기는 것"},{"ko":"양중","en":"","say":"공사에 필요한 자재를 원하는 위치에 적재하는 것","more":"자재관리 순서: 반입, 양중, 저장."},{"ko":"준공청소","en":"","say":"공사가 끝난 현장을 사용자가 바로 쓸 수 있게 치우는 일","more":"조력공을 쓰는 것이 일반적이고, 대형 현장은 청소 전문 업체에 맡기기도 해요."},{"ko":"준공정산","en":"","say":"준공 뒤 공사의 경과와 바뀐 공사비를 정리하는 과정","more":"준공내역서와 준공도면을 만들어요. 계약 당시 공사비 내역서를 기준으로 작성."},{"ko":"준공도면","en":"","say":"변경, 수정사항을 포함한 최종 시공 결과 도면","more":"추후 시설의 유지, 보수에 사용. 준공정산 때 준공내역서와 함께 작성."},{"ko":"준공검사","en":"","say":"시공 결과가 설계도서와 기준에 맞게 완료됐는지 확인하는 검사","more":"준공 순서: 준공청소, 준공정산, 준공검사, 유지관리 계획."},{"ko":"유지관리 계획","en":"","say":"준공 뒤 시설물의 기능과 성능을 지키고 수명을 늘리려고 세우는 계획","more":"하자보수 기간이 끝난 뒤에도 점검, 보수, 교체 자료로 써요."},{"ko":"가설공사","en":"","say":"본 공사를 위해 임시로 설치했다가 끝나면 철거하는 공사","more":"설계도에 일반적으로 표시되지 않고 시방서에 간단한 지시만. 현장소장 책임."},{"ko":"가설재","en":"","say":"가설공사에 쓰는 임시 자재와 시설","more":"직접 공사성 가설재(공사 수행용)와 간접 공사성 가설재(운영 관리용)로 나눠요."},{"ko":"먹매김","en":"","say":"설계도서 치수대로 현장에 1:1로 도면을 옮겨 그리는 작업","more":"설계자, 현장소장, 목수가 참여. 설계자는 먹도면을 준비."},{"ko":"비계","en":"","say":"높은 곳의 작업을 위해 설치하는 임시시설물","more":"종류: 강관(단관)비계, 시스템비계, 조립식(이동틀)비계, 말비계."},{"ko":"강관비계","en":"","say":"외경 약 48.6mm 강관을 클램프로 연결해 세우는 비계","more":"단관비계. 설치 숙련도와 안전관리가 중요. 기둥간격 띠장방향 1.85m, 장선방향 1.5m 이하."},{"ko":"클램프","en":"","say":"강관과 강관을 이어 조여 주는 철물, 커플러라고도 해요","more":"고정 클램프, 회전 클램프, 이형 클램프가 있어요."},{"ko":"안전 발판","en":"","say":"비계 틀 위에서 작업하기 쉽게 까는 발판","more":"갈고리를 단관파이프에 걸어 흔들리지 않게 고정. 걸이 형태에 따라 종류가 나뉘어요."},{"ko":"브라켓","en":"","say":"추락 위험이 있는 곳에 난간대를 붙들어 매는 까치발 모양 철물","more":"외부 비계를 고정할 때도 써요. 발코니용, 측벽용 외줄, 측벽용 쌍줄 브라켓 등이 있어요."},{"ko":"안전 난간대","en":"","say":"작업 발판이나 개구부 가장자리에 세워 추락을 막는 울타리","more":"상부 난간대, 중간 난간대, 발끝막이판으로 구성해요."},{"ko":"띠장","en":"","say":"비계를 앞에서 봤을 때 긴 가로 방향으로 걸리는 수평 부재","more":"띠장방향은 앞에서 본 긴 가로 방향, 띠장간격은 그 가로 부재 사이의 높이예요."},{"ko":"장선","en":"","say":"비계를 옆에서 봤을 때 두께 방향으로 걸리는 수평 부재","more":"장선방향 기둥 간격은 1.5m 이하예요."},{"ko":"가새","en":"","say":"비계가 흔들리지 않게 비스듬히 대는 빗장 부재","more":"슬라이드 그림에서는 40도에서 60도 방향으로 설치하고 기둥에 결속한다고 적혀 있어요."},{"ko":"벽이음","en":"","say":"비계를 건물 벽에 붙들어 매어 넘어지지 않게 하는 연결","more":"슬라이드 그림의 기준은 수평, 수직 방향 5m 이하예요."},{"ko":"시스템비계","en":"","say":"규격화된 부재를 클램프 없이 전용 연결방식으로 조립하는 비계","more":"조립, 해체가 간편하고 최근 사용 확대."},{"ko":"조립식 비계","en":"","say":"공장에서 만든 틀과 부품을 현장에서 조립해 바퀴로 밀고 다니는 비계","more":"이동 틀비계라고도 해요. 고정비계를 설치할 수 없는 경우와 단기간 공사에 사용."},{"ko":"말비계","en":"","say":"다리 형태 지지대 위에 발판을 올린 낮은 높이용 간이 비계","more":"우마라고도 해요."},{"ko":"시저 리프트","en":"Scissor Lift","say":"작업자가 운전해 이동하며 6~15m로 높이를 조절하는 장비","more":"실내에서는 충전식이 바람직."},{"ko":"가설 전기","en":"","say":"공사에 필요한 전력을 임시로 끌어다 쓰는 시설","more":"장비와 조명에 필요한 전력량을 파악해 적정용량의 전원을 공급해야 해요."},{"ko":"가설 분전반","en":"","say":"현장에 임시로 전기를 나눠 주는 노란 전기 상자","more":"박스는 스틸 또는 FRP로 제작. 담당자 이름과 연락처를 적고 시건장치를 달아요."},{"ko":"누전 차단기","en":"","say":"전기가 새거나 과부하가 걸리면 스스로 전기를 끊는 장치","more":"가설 분전함 안에 설치돼 있어요."},{"ko":"안전 릴 케이블","en":"","say":"작업할 장소까지 전선을 감았다 풀었다 하며 늘려 주는 둥근 케이블 통"},{"ko":"가설 조명","en":"","say":"현장 작업을 원활하게 하려고 설치한 임시 조명","more":"가설 투광등과 받침대, 매달기식 가설 전등이 있어요."},{"ko":"보양","en":"","say":"기존 시설이나 완성된 마감재의 파손, 오염을 막는 임시 보호","more":"바닥 타일, 석재 위에는 합판, 도장 때 벽에는 비닐, 코너와 문틀에는 각대."},{"ko":"각대","en":"","say":"벽체 코너와 목재 문틀의 파손을 막으려고 대는 긴 보양재","more":"플라스틱 또는 종이 제품이에요."},{"ko":"고무판","en":"","say":"3~5mm 두께의 연질 보양재","more":"곡면이나 충격이 빈번한 부위에 써요."},{"ko":"에어매트","en":"","say":"작은 공기주머니가 있는 비닐 보양재","more":"비교적 충격이 적은 장소에 써요."},{"ko":"현장사무실","en":"","say":"공사 진행을 위해 현장에 설치한 임시 사무실","more":"가설사무실이라고도 해요. 공사의 규모와 기간을 고려해 설치 여부와 규모를 정해요."},{"ko":"컨테이너 하우스","en":"","say":"컨테이너를 사무공간으로 쓰도록 개조한 현장사무실","more":"이동과 재설치가 간편하고 가격이 저렴하며 방수, 차음, 단열이 우수."},{"ko":"샌드위치 패널","en":"","say":"강판과 강판 사이에 고밀도 폴리스티렌을 채운 패널","more":"단열재가 내장돼 냉난방 효율이 높고 결로를 막아요. 아연도 강판이라 방수, 방습에 강해요."},{"ko":"공사장 가림막","en":"","say":"공사 현장을 시각적으로 가리고 바람을 막는 임시 벽","more":"가설칸막이는 시공할 면적에서 1m 정도를 내어서 설치해요."},{"ko":"가설창고","en":"","say":"공사 관련 기기, 공구류, 중요 자재를 보관하는 임시 창고"},{"ko":"안내간판","en":"","say":"공사개요와 시공회사 등을 적어 현장 입구 벽에 거는 알림판"},{"ko":"철거공사","en":"","say":"새 인테리어 전에 기존 시설과 마감재를 걷어내는 공사","more":"실내는 인력에 의한 철거가 보편적. 폭발력 철거는 거의 안 씀."},{"ko":"철거공사계획","en":"","say":"무엇을, 어떤 순서로, 어떤 장비로 뜯을지 미리 정해 두는 계획","more":"설계도서와 현장 사전조사로 철거 범위, 대상, 공법, 작업량을 파악하고 세워요."},{"ko":"석면","en":"","say":"몸에 해로운 옛 건축재료로, 있으면 별도의 해체 계획이 필요해요","more":"폐석면이 함유된 슬레이트와 텍스 등은 건설폐기물에서 제외돼요."},{"ko":"압쇄공법","en":"","say":"유압의 힘으로 눌러서 콘크리트나 벽돌을 부수는 철거 방법","more":"소음과 진동을 방지하고 폐기물 처리가 쉬우며 철근의 재생이 가능해 경제적."},{"ko":"압쇄기","en":"Crusher","say":"유압으로 콘크리트나 벽돌을 눌러 부수는 집게 모양 장비","more":"소음, 진동이 적고 철근 재생이 가능해 경제적."},{"ko":"백호우","en":"backhoe","say":"팔 끝에 삽이 달린 굴착 장비","more":"기계력에 의한 철거에 쓰는 대표 장비예요."},{"ko":"핸드 브레이커","en":"","say":"공기압을 연결해 콘크리트를 쪼는 손 드릴 장비","more":"전기식과 연료식이 있고 소음이 가장 커요."},{"ko":"스프레더","en":"","say":"쐐기를 틈에 밀어 넣어 벌려서 깨는 철거 장비"},{"ko":"콘크리트 절단기","en":"","say":"고속으로 도는 원형 톱날로 벽체나 슬라브를 잘라 내는 장비","more":"커터기라고도 불러요. 앞뒤로 움직이는 날을 쓰는 것도 있어요."},{"ko":"건설폐기물","en":"","say":"공사에서 나오는 버릴 것들 중 법으로 정해 둔 품목","more":"건설폐기물의 재활용촉진에 관한 법률 시행령이 콘크리트부터 토석까지 지정하고 있어요."},{"ko":"건설폐재류","en":"","say":"폐콘크리트, 폐벽돌, 폐블럭, 폐기와 등 건설 폐기물 묶음","more":"폐아스팔트 콘크리트와 폐토석도 들어가요."},{"ko":"오니","en":"","say":"하수처리나 정수과정에서 생긴 침전물, 슬러지","more":"물에 섞여 가라앉은 진흙 같은 찌꺼기예요."},{"ko":"건설오니","en":"","say":"지하 구조물이나 우물을 시공할 때 나온 흙과 안정화제가 섞인 오니","more":"지반을 단단하게 하려고 주입한 무기물질을 함유한 오니예요."},{"ko":"유리섬유","en":"","say":"유리에 열을 가해 실처럼 가늘게 뽑아낸 것"},{"ko":"암면","en":"Rock wool","say":"현무암 같은 돌을 녹여 실처럼 뽑아낸 불연 단열재","more":"안산암, 사문암, 광재 등을 전기로에 녹여 작은 구멍으로 내뿜으며 냉각시킨 섬유예요."},{"ko":"폐기물 처리 용역","en":"","say":"허가받은 업체에 폐기물 처리를 맡기는 일","more":"위, 수탁 계약서는 3년간 보관해요."},{"ko":"실측","en":"","say":"공사할 공간에 직접 가서 치수를 재는 일","more":"단위는 mm로 적어요. 순서는 평면도, 입면도, 천장도."},{"ko":"레이저 줄자","en":"","say":"빛을 쏘아 거리를 재 주는 줄자","more":"긴 거리나 천장고를 잴 때 좋아요."},{"ko":"평면도","en":"","say":"공간을 위에서 내려다본 것처럼 그린 도면"},{"ko":"입면도","en":"","say":"벽을 정면에서 바라본 것처럼 그린 도면","more":"각 방의 네 면을 모두 그려요."},{"ko":"천장도","en":"","say":"천장을 올려다본 모습을 그린 도면"},{"ko":"천장고","en":"","say":"바닥에서 천장까지의 높이","more":"각 방에서 양 끝과 중앙 3군데를 재서 가장 낮은 치수로 정해요."},{"ko":"커튼박스","en":"","say":"커튼 레일을 감추려고 천장 가장자리에 만든 홈"},{"ko":"우물조명","en":"","say":"천장을 우물처럼 파 넣고 그 안에 빛을 넣은 조명"},{"ko":"점검구","en":"","say":"천장 속 설비를 점검하려고 뚫어 둔 뚜껑 달린 구멍"},{"ko":"공정계획","en":"process planning","say":"착공부터 준공까지 기간 내 좋은 품질로 안전하게 진행하도록 짜는 계획","more":"요소: 시기, 내용, 수량, 인력. 수단: 인력, 장비, 자금, 자원."},{"ko":"네트워크 공정표","en":"Network","say":"작업의 시작, 완료와 연계를 원과 화살표로 표시하는 공정표","more":"전체 파악과 상호 관계가 명확. 작성에 시간과 전문성이 필요."}],"3":[{"ko":"경량철골","en":"","say":"목재 대신 철재로 벽틀과 천장틀을 짜는 소재 또는 제품","more":"장점: 불연, 자중 감소, 공기 단축, 내화와 차음 성능 구현, 설비 설치 간단."},{"ko":"메탈 스터드","en":"Metal Stud","say":"경량 벽체 틀을 이루는 세로 기둥 부재","more":"런너, 보강 채널과 함께 벽체 틀을 구성."},{"ko":"건식벽체","en":"Dry-Wall","say":"스터드 골조와 석고보드로 구성한 벽체","more":"기본 구성: 스터드 + 흡음충진재 + 석고보드 + 마감재."},{"ko":"건식공법","en":"","say":"물을 쓰지 않아 습식의 중량화와 긴 공기를 보완한 공법"},{"ko":"LGS","en":"Light Gauge Structure","say":"경량천장틀을 부르는 이름","more":"천장 틀은 캐링채널, 행거, 행거볼트와 M-Bar, T-Bar 시스템."},{"ko":"아연 도금","en":"","say":"경량 형강 표면에 녹을 막으려고 입힌 처리"},{"ko":"C-스터드","en":"C-Stud","say":"가장 일반적인 스터드, 주로 65mm를 450mm 간격으로 설치","more":"300 또는 450mm 간격. 길이 2,400~5,000mm 비규격이라 천장고 실측 후 발주."},{"ko":"CH-스터드","en":"CH-Stud","say":"바닥 슬라브가 없어 한쪽 면에서만 시공할 때 쓰는 스터드","more":"계단실, 대형 통풍구, 고층 수직 샤프트 등 내화, 차음이 필요한 곳."},{"ko":"E-스터드","en":"E-Stud","say":"외벽 접합부와 CH-스터드 마무리, 2중 스터드에 쓰는 스터드"},{"ko":"스틸런너","en":"Steel Runner","say":"천장과 바닥면에 고정해 스터드를 고정하는 부재","more":"용융 강판 소재."},{"ko":"J 런너","en":"J Runner","say":"CH-스터드와 함께 쓰며 높은 쪽을 OPEN공간으로 두는 런너","more":"샤프트, 엘리베이터 공간 등."},{"ko":"퍼링 채널","en":"Furring Channel","say":"외벽에 석고보드를 바로 붙일 때 610mm 간격으로 세우는 모자형 채널","more":"방수 처리된 석고보드로 마감."},{"ko":"보강 채널","en":"Brace Channel","say":"높은 곳 스터드의 흔들림을 잡으려고 가로로 끼우는 채널","more":"스터드 높이 4m 이상이면 1,800mm 간격 보강."},{"ko":"메탈 트림","en":"Metal Trim","say":"끼운 뒤 나사못으로 고정하고 컴파운드로 메우는 석고보드 끝단 보호재"},{"ko":"케이싱 비드","en":"Casing Bead","say":"단순히 끼워서 쓰는 석고보드 끝단 보호재"},{"ko":"코너 비드","en":"Corner Bead","say":"벽체가 직각으로 꺾이는 코너의 파손을 막는 제품"},{"ko":"석고보드","en":"Gypsum Board","say":"스터드 뼈대 양쪽에 붙이는 판, 벽의 살에 해당","more":"일반적으로 9.5mm나 12.5mm를 2겹으로 시공. 규격은 900 x 1,800, 1,200 x 2,400."},{"ko":"1ply","en":"","say":"석고보드를 한 겹 붙이는 것, 원플라이","more":"1ply와 2ply 경계선은 엇갈리게 시공."},{"ko":"2ply","en":"","say":"석고보드를 두 겹 붙이는 것, 투플라이","more":"9.5mm 2겹 양면 벽 두께 103mm, 12.5mm면 115mm. 도면에는 100mm."},{"ko":"흡음충진재","en":"","say":"스터드 사이에 넣어 소리를 빨아들이는 재료"},{"ko":"단열재","en":"INSULATION","say":"EPS, XPS, 글라스울, 미네랄울 등 단열 재료의 총칭","more":"건식벽체는 한쪽 보드를 붙인 뒤 스터드 사이에 단열재를 충진."},{"ko":"조인트 테이프","en":"","say":"석고보드 이음매에 부풀음 없이 붙이는 테이프"},{"ko":"조인트 컴파운드","en":"","say":"보드 이음매를 메우고 24시간 정도 경화시키는 재료"},{"ko":"스터드 2겹치기","en":"","say":"문이나 창 자리의 개폐 충격을 흡수하도록 스터드를 겹친 보강"},{"ko":"먹매김","en":"","say":"설계도서 치수대로 현장에 1:1로 도면을 옮겨 그리는 작업"},{"ko":"차음시트","en":"","say":"석고보드 사이에 넣어 소리를 막는 시트","more":"예: 일반 석고보드 1ply + 차음시트 + 차음 석고보드."},{"ko":"방진고무","en":"","say":"저음을 제어하는 데 쓰는 방음 재료"},{"ko":"흡음 마감재","en":"","say":"목모보드, 타공보드, 아트보드처럼 소리를 흡수하는 마감재"},{"ko":"달대","en":"hanger","say":"천장틀을 구조체에 매달아 지지하는 부재","more":"달대 높이 1.5M 이상이면 C-형강 등으로 보강 틀."},{"ko":"달대 볼트","en":"hanger bolt","say":"달대로 쓰는 직경 9mm 이상의 전산볼트 형태 부재","more":"행거볼트. 약 900mm 간격. 상부는 스트롱 앵커나 인서트, 하부는 행거 클립으로 고정."},{"ko":"스트롱 앵커","en":"","say":"망치로 두들기면 머리 부분이 벌어지며 천장에 고정되는 철물","more":"앵커 간격 900~1,200mm."},{"ko":"인서트","en":"","say":"볼트를 달려고 미리 콘크리트에 매입해 둔 철물"},{"ko":"양날 브라켓","en":"","say":"콘크리트나 스트롱 앵커 설치가 어려운 각 파이프 등에 쓰는 고정 철물"},{"ko":"행거 클립","en":"","say":"행거볼트와 캐링채널을 고정하는 부속","more":"볼트를 살짝 풀어 두어야 나중에 천장 높이를 조절할 수 있어요."},{"ko":"캐링 채널","en":"carrying channel","say":"행거에 약 900mm 간격으로 거는 천장틀의 주 골조","more":"천장 하중을 행거를 통해 구조체로 전달. 벽에서 50mm 이하, 엇갈리게 시공, 연결 시 조인트 사용."},{"ko":"마이너 채널","en":"Minor Channel","say":"캐링 채널과 직교해 약 3,000mm 간격으로 거는 보강 채널","more":"시공 그림 기준 2,000~3,000mm."},{"ko":"M-Bar","en":"","say":"캐링 채널 아래 300mm 간격으로 걸고 보드를 나사로 박는 폐쇄형 천장틀","more":"가장 기본, 가장 많이 씀. 순서: 앵커, 테두리 몰딩, 행거, 캐링, 마이너, M-Bar, 수평, 1ply, 2ply."},{"ko":"M-Bar 클립","en":"","say":"M-Bar를 캐링채널에 고정하는 클립","more":"한쪽 방향으로만 고정하면 뒤틀릴 수 있어 엇갈림 시공."},{"ko":"테두리 몰딩","en":"","say":"벽 둘레에 천장 마감 높이를 그려 주듯 먼저 붙이는 몰딩","more":"고정못 간격은 600mm 이하예요. 넘으면 몰딩이 처져 수평이 안 맞아요."},{"ko":"T-Bar","en":"","say":"격자로 짠 T자 틀의 날개 위에 규격 패널을 얹어 놓는 탈착형 천장틀","more":"패널을 손으로 들어 올릴 수 있어서 따로 점검구를 만들지 않아도 돼요."},{"ko":"메인 T-Bar","en":"","say":"캐링 채널과 직교해 610mm 간격으로 다는 T-Bar의 큰 줄기","more":"캐링 채널에 C/T 클립으로 체결해요."},{"ko":"크로스 T-Bar","en":"","say":"메인 T-Bar 옆구리 홈에 끼워 격자를 완성하는 짧은 T-Bar","more":"한쪽을 먼저 넣고 비스듬히 돌려 나머지를 끼워요."},{"ko":"C/T 클립","en":"","say":"캐링 채널과 메인 T-Bar를 물려 주는 클립","more":"Carrying 과 T-Bar 의 머리글자예요."},{"ko":"마이톤","en":"","say":"가장 많이 쓰는 600x600 크기의 T-Bar용 천장재","more":"쓰는 마감재 크기가 달라지면 T-Bar 간격도 함께 바뀌어요."},{"ko":"집톤","en":"Gyptone","say":"두께 9mm, 603x603mm 규격의 T-Bar용 천장재","more":"전기와 설비 공정이 다 끝난 뒤에 올려요. 배면의 화살표 방향을 맞춰 설치해요."},{"ko":"T&H-Bar","en":"","say":"천장재 측면을 H-Bar로 연결해 줄눈과 피스가 안 보이게 한 천장 시스템","more":"T-Bar 단독보다 천장면의 일체성과 안정성이 높아요."},{"ko":"SGP 칸막이","en":"Steel Gypsum Panel","say":"도장한 강판과 석고보드를 결합해 만든 조립식 패널형 칸막이","more":"해체와 재설치가 쉬워 사무실, 업무공간에 많이 써요."},{"ko":"큐비클","en":"Cubicle","say":"코어재 양면에 HPL을 붙인 화장실용 조립식 패널 칸막이","more":"습기가 많은 곳이라 내수성, 내식성, 내오염성이 좋은 제품을 골라요."},{"ko":"시스템 칸막이","en":"","say":"프레임, 패널, 유리, 도어를 공장에서 만들어 현장에서 조립하는 모듈형 칸막이","more":"SGP 칸막이보다 디자인이 다양하고 개방성과 프라이버시를 조절할 수 있어요."},{"ko":"레이스웨이","en":"","say":"노출천장에 전산볼트로 매달아 조명을 다는 긴 레일","more":"3M 전산볼트를 1.5M로 잘라서 씁니다."},{"ko":"톱니형 경량철골","en":"","say":"천장 속이 아주 좁은 아파트 천장에 쓰는 톱니 모양 경량철골 자재","more":"톱니형 달대와 톱니형 케리어바를 써서 높이를 조금씩 맞춰요."},{"ko":"상세도","en":"","say":"특정 부위를 어떤 재료와 치수, 순서로 시공할지 보여 주는 도면","more":"상세도를 그린다는 말은 디테일을 푼다는 말이에요."},{"ko":"덧붙이는 벽","en":"","say":"기존 콘크리트나 조적 벽 위에 한쪽 면만 마감하는 경량 벽체","more":"C-스터드 65 + 9.5mm 2겹 = 84mm. 빈 공간에 새로 세우는 벽은 양면이에요."},{"ko":"줄퍼티","en":"","say":"1차로 석고보드의 이음매만 줄처럼 메우는 퍼티 작업"},{"ko":"올퍼티","en":"","say":"2차로 도장면 전체를 균질하게 하고 발색력을 높이는 퍼티 작업"},{"ko":"조인트 컴파운드","en":"JOINT COMPOUND","say":"보드 이음매를 메우고 24시간 정도 경화시키는 재료"}],"4":[{"ko":"구조적 측면","en":"","say":"벽체, 칸막이 속처럼 노출되지 않는 기본 틀을 만드는 목재의 쓰임","more":"짝은 치장적 측면. 요즘 구조공사의 목재 비중은 줄고 마감, 가구공사 비중이 커짐."},{"ko":"치장적 측면","en":"","say":"걸레받이, 창호, 바닥, 계단, 핸드레일, 가구처럼 목재 자체가 노출되는 쓰임","more":"마감 성격. 짝은 구조적 측면."},{"ko":"비중","en":"","say":"같은 부피의 물과 비교해 그 물질이 얼마나 무거운지 나타내는 값","more":"목재 비중 = 나무 밀도 / 물 밀도. 침엽수 0.3~0.5, 활엽수 0.5~0.9. 클수록 강도는 오르고 수축, 뒤틀림도 커짐."},{"ko":"수심","en":"Pith","say":"나무 줄기의 한가운데 중심","more":"횡단면 3부분 : 수심, 목질부, 수피."},{"ko":"수피","en":"Bark","say":"나무의 껍질 부분","more":"수분과 영양을 섭취. 오래된 나무일수록 껍질이 두꺼움."},{"ko":"나이테","en":"Growth ring","say":"1년에 한 줄씩 생기는 고리 모양 부분, 연륜이라고도 함","more":"춘재와 추재가 반복되며 형성."},{"ko":"춘재","en":"Earlywood","say":"봄에 자라 세포가 크고 면적이 넓은 나이테 부분","more":"물 공급 충분, 세포분열 활발, 물관 발달. 짝은 추재."},{"ko":"추재","en":"Latewood","say":"한여름부터 느리게 자라 세포벽이 두껍고 치밀한 부분","more":"하재라고도 함. 짝은 춘재."},{"ko":"심재","en":"Heartwood","say":"수심 가까이 짙은 색의, 수액 전달을 멈춘 단단한 속 부분","more":"수분 적고 변형 거의 없음, 강도와 내구성 큼, 깎으면 광택. 오크, 월넛, 체리는 주로 심재를 씀."},{"ko":"변재","en":"Sapwood","say":"표피 가까이 옅은 색의, 수액을 나르는 살아 있는 바깥 부분","more":"함수율 높고 무름, 켠 뒤에도 변형, 균열. 수축률이 심재보다 큼. 메이플, 자작, 애쉬는 변재도 많이 씀."},{"ko":"기건 비중","en":"","say":"목재의 수분을 공기 중에서 뺀 상태의 비중","more":"비중은 수종, 밀도, 연륜, 수령, 변재, 심재에 따라 다름."},{"ko":"함수율","en":"","say":"목재가 물을 머금은 정도","more":"낮을수록 강도가 큼. 공식 (건조 전 중량 - 절건 중량) / 절건 중량 × 100. 예제 15kg, 전건 10.8kg이면 38.89%."},{"ko":"섬유포화점","en":"","say":"자유수는 빠지고 세포막 속 흡착수만 남은 함수율 30% 정도의 상태","more":"이상에서는 강도 변화 없음, 이하에서는 마를수록 강도 증가. 자연건조로 수분의 70% 제거된 지점."},{"ko":"자유수","en":"Free water","say":"세포 안 통로(수관, 체관)에 고인 물","more":"흡착수와 약 7:3. 자연건조로 먼저 빠짐."},{"ko":"흡착수","en":"Bound water","say":"세포벽 속에 스며든 물","more":"인공(강제) 건조로 제거. 빠지면 단단해지지만 부피가 줄고 균열."},{"ko":"기건재","en":"","say":"공기 중에서 더 이상 마르지 않는 상태까지 자연 건조된 목재","more":"함수율 15% (10~15%). 대기 중 노출 상태."},{"ko":"전건재","en":"","say":"인공적으로 완전히 말려 함수율이 0%인 목재","more":"절건재라고도 함. 외력으로 강제로 수분 제거. 함수율 표 : 전건재 0, 기건재 15, 섬유포화점 30, 구조재 20(25 이하), 수장재 15(18 이하)."},{"ko":"둘레 방향 수축","en":"Tangential shrinkage","say":"나이테를 따라 도는 방향의 수축, 가장 큼","more":"수직 방향의 1.5~2배. 순서 : 둘레 > 수직 >>> 길이."},{"ko":"수직 방향 수축","en":"Radial shrinkage","say":"나이테에 수직인 반지름 방향의 수축","more":"둘레 방향보다 작고 길이 방향보다 큼."},{"ko":"종 방향 수축","en":"longitudinal shrinkage","say":"목재 길이 방향의 수축, 거의 일어나지 않음","more":"수축변형 : 줄기(길이) < 반지름(수직) < 나이테 접선(둘레)."},{"ko":"인장 강도","en":"Tensile Strength","say":"양쪽으로 잡아당길 때 버티는 힘","more":"결방향이 결수직방향보다 강함. 결수직 인장은 설계 상 회피. 강도 순서 1위."},{"ko":"압축 강도","en":"Compressive Strength","say":"길이 방향으로 양쪽에서 누를 때 버티는 힘","more":"대표 부재는 기둥. 결방향이 결수직방향보다 3~8배 강함."},{"ko":"휨 강도","en":"Bending Strength","say":"두께 방향 하중으로 휘려 할 때 버티는 힘","more":"압축 강도의 약 1.75배. 길이 L, 압력 P 크면 변형 심함, 너비 b, 깊이 d 크면 변형 줄어듦."},{"ko":"전단 강도","en":"Shear Strength","say":"단면을 위아래로 엇갈려 끊으려는 힘에 버티는 힘","more":"섬유방향과 수직일 때 더 큼. 강도 순서 : 인장 > 휨 > 압축 > 전단."},{"ko":"결수직방향","en":"","say":"목재 섬유방향과 수직인 방향, 횡단방향","more":"약한 3가지 : 결수직 압축에 의한 변형, 결수직 인장에 의한 파괴, 결방향 전단에 의한 파괴."},{"ko":"가압수축","en":"compression shrinkage","say":"결수직방향 압축으로 비례한계를 넘어 눌린 변형이 남는 문제","more":"파괴보다 변형이 문제. 장부 결합에서 잠재적 문제."},{"ko":"장부","en":"Tenon","say":"다른 부재의 구멍에 끼우도록 끝을 가늘고 길게 만든 부분","more":"눌리는 변형이 생기므로 적절한 크기로 접촉면적 확보."},{"ko":"침엽수재","en":"Softwood","say":"바늘잎 나무의 목재, 소프트 우드","more":"연목. 건조 빠름, 크고 긴 재료. 삼나무, 소나무, 전나무, 잣나무, 낙엽송. 건축재 선호."},{"ko":"활엽수재","en":"Hardwood","say":"넓은잎 나무의 목재, 하드 우드","more":"경목. 건조에 오래 걸림, 다양한 모양. 자작나무, 물푸레나무, 벚나무, 흑단, 너도밤나무, 마호가니, 단풍나무. 가구 선호."},{"ko":"경량철골","en":"","say":"목재 대신 철재로 벽틀과 천장틀을 짜는 소재 또는 제품","more":"장점: 불연, 자중 감소, 공기 단축, 내화와 차음 성능 구현, 설비 설치 간단."},{"ko":"메탈 스터드","en":"Metal Stud","say":"경량 벽체 틀을 이루는 세로 기둥 부재","more":"런너, 보강 채널과 함께 벽체 틀을 구성."},{"ko":"합판","en":"Plywood","say":"얇은 단판을 섬유방향이 직교하게 홀수 겹 붙인 판재","more":"단판 0.5~1.5mm, 3, 5, 7겹. 두께 3~24mm, 3x6자 910x1,820, 4x8자 1,220x2,440(주로)."},{"ko":"구조용재","en":"","say":"실내 건축에서 뼈대 역할을 하는 목재","more":"강도와 내구성 필요, 수축팽창이 작고 내부식성이 큰 것."},{"ko":"치장용재","en":"","say":"마무리 공사에 쓰여 그대로 마감이 되는 목재, 수장용재라고도 함","more":"색상과 무늬결이 아름답고 쉽게 마모되지 않는 것."},{"ko":"자연건조","en":"","say":"대기의 온도, 습도, 바람으로 자연 그대로 말리는 방법","more":"간단하고 시설비 적음, 인공 건조의 선행 과정. 6개월~3~5년, 함수율 25~30% 내외."},{"ko":"인공 건조","en":"","say":"건조실의 온도, 습도, 풍속을 조절해 말리는 방법","more":"낮은 함수율까지 가능, 자연 조건 영향 없음, 설치비와 유지비 높음, 체적 감소와 균열."},{"ko":"정목","en":"quarter sawn","say":"나이테와 직각으로 중심을 향해 켠 판재, 곧은 결재","more":"변형, 마모 적어 이상적. 넓은 판이 적게 나와 비쌈."},{"ko":"판목","en":"flat sawn","say":"나이테 방향을 무시하고 켠 판재, 널 결재","more":"결이 물결 모양 곡선. 곧은 결재보다 갈라짐, 틀어짐이 많음."},{"ko":"곧은결","en":"","say":"나이테에 직각방향으로 켠 면에 나타나는 평행선 나뭇결","more":"수축, 변형, 마모 적음. 창호재, 장식재, 가구재."},{"ko":"널결","en":"","say":"나이테에 평행방향으로 켠 면에 나타나는 물결 모양 나뭇결","more":"결이 거칠고 불규칙, 변형과 마모 큼. 주로 장식재."},{"ko":"엇결","en":"","say":"나무 섬유가 꼬여 나뭇결이 어긋나게 나타난 상태","more":"엇결이 난 목재는 엇결재."},{"ko":"무늬결","en":"","say":"여러 원인으로 소용돌이처럼 복잡하게 생긴 아름다운 나뭇결","more":"주로 장식재."},{"ko":"재래 단위","en":"","say":"푼, 치, 자로 재는 옛 목재 치수 단위","more":"푼 3mm, 치 30mm, 자 300mm. 2001년부터 사용 금지, 치수는 주로 300mm 단위."},{"ko":"각재","en":"","say":"막대기 모양으로 각지게 켠 목재","more":"두께 75mm 미만, 폭이 두께의 4배 미만 또는 두께와 폭 모두 75mm 이상. 30, 45, 60, 75, 90각. 대부분 3,600mm."},{"ko":"평각재","en":"","say":"단면이 직사각형인 각재","more":"짝은 정각재(정사각형). 현장 통칭 중각재, 투바이. 30×69 / 38×64 등."},{"ko":"소각재","en":"","say":"현장 용어 다루끼, 가장 가는 각재","more":"28×28 또는 30×30. 가구 프레임, 벽체 틀. 대각재(오비끼)는 81×81 / 89×89, 문틀."},{"ko":"정척물","en":"","say":"1.8m, 2.7m, 3.6m 길이의 각재","more":"3.6m가 가장 많이 씀. 장척물 4.5, 5.4, 6.3m / 단척물 1.8m 이하 / 난척물 2.1, 2.4, 3.0m."},{"ko":"나왕","en":"lauan","say":"색이 아름답고 가공이 쉬운 각재 수종, 라왕이라고도 함","more":"적나왕과 백나왕. 문틀, 문짝, 가구, 바닥재. 미송은 나왕보다 저가."},{"ko":"단판","en":"","say":"원목을 얇게 깎은 한 장의 박판, 베니어","more":"단판 여러 겹인 합판을 베니어판이라 부르는 것은 잘못."},{"ko":"특수합판","en":"","say":"표면에 오버레이, 프린트, 도장 등을 가공한 합판","more":"짝은 보통합판(표면가공 없음). 용도별 : 내수, 방충, 방화, 방부합판."},{"ko":"취부","en":"","say":"석고보드, 합판 등을 붙이는 것을 부르는 현장 용어","more":"벽은 9.5mm 2겹(2 플라이 치기). 1겹째 나사못, 2겹째 본드 + 나사못, 이음매 어긋나게."},{"ko":"무늬목","en":"Wood Veneer","say":"원목을 0.2mm로 종이처럼 얇게 뜬 장식재","more":"석고보드, 합판에 가열, 가압으로 부착. 들뜸, 터짐 하자. 1mm 이상 후판은 배접 생산."},{"ko":"MDF","en":"Medium Density Fiber Board","say":"나무를 톱밥처럼 부숴 합성수지로 굳힌 중밀도 섬유판","more":"방향성 없음, 가공성 좋음. 수축되기 쉽고 습기에 약하며 합판보다 약함. 1,220×2,440, 3~30mm, 18T 주로 사용. 도장은 프라이머 필수."},{"ko":"파티클 보드","en":"Particle Board","say":"목재 조각을 잘게 부순 칩을 붙인 자원 절약형 판, PB, 칩 보드","more":"흡음성, 단열성 좋음, 단면이 거칠어 측면 가공 필요. 두께 9~35mm. 씽크대, 가구."},{"ko":"반자틀","en":"","say":"나무 천장에서 보드를 붙이는 바탕 목틀","more":"소규모 공사용. 각재 간격 300 또는 450mm. 위로 반자틀받이, 달대, 달대받이."},{"ko":"달대","en":"hanger","say":"천장틀을 구조체에 매달아 지지하는 부재","more":"달대 높이 1.5M 이상이면 C-형강 등으로 보강 틀."},{"ko":"달대 볼트","en":"hanger bolt","say":"달대로 쓰는 직경 9mm 이상의 전산볼트 형태 부재","more":"행거볼트. 약 900mm 간격. 상부는 스트롱 앵커나 인서트, 하부는 행거 클립으로 고정."},{"ko":"캐링 채널","en":"carrying channel","say":"행거에 약 900mm 간격으로 거는 천장틀의 주 골조","more":"천장 하중을 행거를 통해 구조체로 전달. 벽에서 50mm 이하, 엇갈리게 시공, 연결 시 조인트 사용."},{"ko":"M-Bar","en":"","say":"캐링 채널 아래 300mm 간격으로 걸고 보드를 나사로 박는 폐쇄형 천장틀","more":"가장 기본, 가장 많이 씀. 순서: 앵커, 테두리 몰딩, 행거, 캐링, 마이너, M-Bar, 수평, 1ply, 2ply. 타카 사용 금지."},{"ko":"퍼티","en":"putty","say":"바탕면의 요철, 흠집, 균열, 접합부를 메워 평평하게 만드는 재료","more":"현장 말 '빠데'. 접착력이 좋고 경화 후 연마가 잘돼야 함. 주재 + 경화제를 섞으면 2액형 퍼티."},{"ko":"실러","en":"sealer","say":"바탕면의 흡수성을 조절하고 윗칠의 부착성을 높이는 하도용 도료","more":"슬라이드 표기 '실라 / 실러'. 콘크리트, 모르타르용 실러, 목재용 샌딩실러. 쵸킹이 생긴 구도막에도 사용."},{"ko":"스테인","en":"stain","say":"목재 무늬를 그대로 보이게 하면서 색만 입히는 착색재","more":"덮지 않고 침투하거나 얇게 착색. 표면 보호 성능이 제한적이라 바니쉬, 우레탄, 래커 등 투명 마감재를 추가로 칠함."},{"ko":"정각재","en":"","say":"단면이 정사각형인 각재","more":"횡단면이 정사각형이면 정각재, 직사각형이면 평각재."},{"ko":"미송","en":"pine","say":"북아메리카, 영국, 유럽 등지의 소나무과 나무로 만든 각재 수종","more":"나왕에 비해 비교적 저가. 부드럽고 향기가 좋으며 색이 밝고 은은해 장식적인 목적으로도 씀."},{"ko":"소송","en":"","say":"러시아산(구 소련) 소나무로 만든 각재","more":"연하고 곧으며 옹이가 적고 색이 밝음. 못, 타카핀을 많이 박는 내장재. 미송보다 단가가 비쌈."},{"ko":"뉴송","en":"","say":"뉴질랜드 소나무로 만든 각재","more":"가격은 저렴하지만 내구성이 좋지 않아 옹이 주변에 못을 잘못 박으면 갈라지거나 깨짐. 내장재로 많이 씀."},{"ko":"코아 합판","en":"Core Plywood","say":"띠 모양 각목 심 위아래에 단판을 붙인 판재","more":"정확한 명칭 Batten Board. 두께 18~25mm. 띠로 잘라 각재 대신 틀로 쓰기도 함."},{"ko":"OSB","en":"Oriented Strand Board","say":"얇은 직사각형 나무 조각을 직각으로 겹쳐 내수수지로 누른 판","more":"포장 합판. 조각은 부산물이 아니라 특별히 제조. 파티클 보드보다 강함. 파티션, 가구, 최종 마감."},{"ko":"집성목","en":"Glue-Laminated Timber","say":"각재를 섬유방향 평행하게 접착해 모은 목재","more":"변형 적고 긴 장척재. 구조용 집성목, 수장용 집성목. 합판은 직교, 집성목은 평행."},{"ko":"핑거 조인트","en":"Finger-Joint","say":"손가락 깍지처럼 끝을 맞물려 길이 방향으로 잇는 접합","more":"짝은 스카프 조인트(Scarf-Joint, 비스듬히 깎아 잇기). 구조용 집성목에 포함."},{"ko":"흡음패널","en":"Acoustic panel","say":"강당, 연주 공간에 쓰는 흡음용 목재 마감 판재","more":"코펜하겐 리브를 대신하는 저렴한 재료. 흡음재료는 다공성."},{"ko":"로터리 컷","en":"","say":"원목을 돌리며 두루마리 풀듯 단판을 깎는 방법","more":"나이테를 따라 깎여 폭이 넓고 판목상 무늬. 짝은 슬라이스 컷(고정하고 칼로 저밈)."},{"ko":"템바보드","en":"Tambour Board","say":"막대를 반복 배열해 세로나 가로 요철을 만든 장식 마감재","more":"벽체, 가구 전면, 카운터, 기둥. 홈에 먼지, 돌출부 손상 주의."},{"ko":"원목마루","en":"","say":"통원목이나 두꺼운 원목 단판을 쓴 가장 비싼 마루","more":"샌딩 후 재도장 가능, 정전기 없음. 습기와 온도 변화에 약함. 합판 위 무늬목 2mm 이상."},{"ko":"합판마루","en":"","say":"합판 위에 천연 무늬목을 붙인 마루, 온돌마루","more":"치수 안정성 높고 바닥난방에 적합, 긁힘에 약함. 무늬목 2mm 이하. 중/고가."},{"ko":"강화마루","en":"","say":"HDF 위에 무늬층을 얹어 접착제 없이 클릭으로 끼우는 마루","more":"현가식, 비접착식, 저가. 시공, 철거 쉬움, 보행 소음, 습기 주의. 걸레받이와 사이 실리콘 금지."},{"ko":"강마루","en":"","say":"합판 위에 인쇄 무늬층을 얹어 바닥에 본드로 붙이는 마루","more":"접착식, 중가. 들뜸, 울림 적고 열전달 유리. 철거와 부분 교체 어려움. 아파트에 많이 씀."},{"ko":"HDF","en":"","say":"목질섬유를 고밀도로 압축한 섬유판","more":"강화마루 바탕재. 수분을 흡수하면 팽창, 변형."},{"ko":"슬라이스 컷","en":"","say":"원목을 고정해 두고 칼로 단판을 한 장씩 저며 뜨는 방법","more":"56쪽 그림: 슬라이서, 단판, 칼, 고정. 짝은 원목을 돌려 두루마리처럼 푸는 로터리 컷이에요."},{"ko":"스카프 조인트","en":"Scarf-Joint","say":"두 부재 끝을 비스듬히 깎아 겹쳐 붙여 길이 방향으로 잇는 접합","more":"구조용 집성목에 쓰는 길이방향 이음이에요. 짝은 손가락 깍지 모양의 핑거 조인트예요."},{"ko":"현가식","en":"","say":"바닥에는 붙이지 않고 마루판끼리만 결합해서 올려놓는 시공 방식","more":"강화마루의 시공 방식이에요. 그래서 바탕면의 평활도(평평한 정도)가 중요해요."},{"ko":"비접착식","en":"","say":"바닥에 본드로 붙이지 않고 마루끼리만 끼워 올려놓는 시공 방식","more":"마루판재 비교표에서 강화마루만 비접착식이에요. 강마루, 합판마루, 원목마루는 바닥면에 본드로 직접 붙이는 접착식이에요."},{"ko":"오버레이지","en":"","say":"강화마루, 강마루의 층 구성에서 맨 위(①)에 덮는 층","more":"그 아래 ② 표면장식지(무늬층)를 덮어 지켜요. 합판마루, 원목마루는 맨 위층을 표면처리층이라고 불러요."},{"ko":"표면장식지","en":"","say":"나무 무늬를 찍어 넣은 장식 종이 층(②)","more":"강화마루는 HDF 위, 강마루는 합판 위에 표면장식지를 얹어요. 합판마루, 원목마루는 이 자리에 천연무늬목을 써요."},{"ko":"몰딩","en":"","say":"벽, 천장, 문, 가구의 경계나 이음부를 마감하고 장식하는 띠 모양 부재","more":"종류는 원목 몰딩, 래핑 몰딩, 기타(석고, 우레탄, 플라스틱). 위치로는 천장 몰딩, 걸레받이, 허리몰딩."},{"ko":"원목 몰딩","en":"","say":"건조된 원목을 가공해 원목 고유의 자연스러운 무늬를 살린 몰딩","more":"짝은 래핑 몰딩(MDF, 파티클 보드 겉에 무늬목이나 인조 시트를 씌운 것)."},{"ko":"래핑 몰딩","en":"","say":"MDF, 파티클 보드 표면에 무늬목이나 인조 시트를 씌운 몰딩","more":"짝은 원목 몰딩. 위치별 : 천장 몰딩, 걸레받이, 허리몰딩."},{"ko":"천장 몰딩","en":"","say":"내벽과 천장이 만나는 부분에 대는 몰딩","more":"위치로 부르는 몰딩 세 가지 : 천장 몰딩, 걸레받이, 허리몰딩."},{"ko":"걸레받이","en":"","say":"바닥과 벽이 만나는 부분에 대는 몰딩","more":"마루와 걸레받이 사이에는 실리콘 처리를 하지 않아요(수축현상). 비교표에서 강화마루는 걸레받이가 두껍다고 적혀 있어요."},{"ko":"허리몰딩","en":"","say":"벽 중간 부분에 가로로 대는 몰딩","more":"걸레받이, 상부 몰딩과 함께 수평 기준선(먹선)을 기준으로 높이를 정해요."},{"ko":"레벨기","en":"","say":"액체 속 기포나 레이저 광선으로 수평과 수직을 맞추는 도구","more":"벽체 틀을 세울 때, 철골작업, 철물작업에 써요. 요즘은 레이저 레벨기를 주로 써요."},{"ko":"경사 측정기","en":"","say":"경사면의 각도를 재거나 구배, 각도를 설정하는 공구","more":"요즘은 디지털 소형 측정기를 쓰고, 레이저 측정기에 기능이 함께 들어간 경우도 있어요."},{"ko":"줄자","en":"","say":"말려 있는 띠 자를 당겨 거리나 길이를 재는 도구","more":"2m, 3m, 5m, 10m, 20m, 30m, 50m, 100m 등이 있어요. 먼 거리는 레이저 측정기를 주로 써요."},{"ko":"직각 스틸자","en":"","say":"목재를 재단, 가공할 때 직각을 정확하게 재는 ㄱ자 모양 쇠자","more":"목수들이 지니는 가장 기본적인 공구예요."},{"ko":"먹통","en":"","say":"먹매김할 때 쓰는 목수의 가장 기본 휴대 장비","more":"목재 재단 면 표시, 바닥, 벽, 천장에 자리 표시."},{"ko":"전기 톱","en":"","say":"전동 모터로 원형 톱날을 고속 회전시켜 자르는 공구","more":"목재, 합판, MDF 등을 절단, 가공해요. 주로 작업대에 고정하고 2인 1조로 작업해요."},{"ko":"띠 톱","en":"","say":"둥근 고리 모양의 띠 톱날을 기계에 걸어 고속으로 돌려 자르는 톱","more":"띠 모양 강철판 한쪽 가장자리에 톱니를 내고 양 끝을 이어 고리로 만들어요. 톱니는 자르는 재료에 따라 골라요."},{"ko":"줄 톱","en":"Jig saw","say":"지그재그로 직선, 원형을 자르거나 모양을 따내는 톱","more":"직소기라고도 함. 지그재그로 자를 수 있다는 기능에서 생긴 이름."},{"ko":"각도커팅기","en":"","say":"여러 각도로 정밀하게 자르는 공구","more":"규준대로 같은 규격을 반복 절단해요. 윗부분의 원형 날이 아래로 슬라이딩하며 재단해요."},{"ko":"대패","en":"","say":"목재의 끝마무리, 치수 맞추기, 표면 다듬기에 쓰는 공구","more":"막대패, 중간대패, 다듬질대패로 구분해요."},{"ko":"전동 대패","en":"","say":"회전축의 대팻날을 고속으로 돌려 목재 표면을 평활하게 깎는 목공기계","more":"휴대용 전동대패와 작업대에 고정하는 대패기계가 있어요. 절삭 깊이로 한 번에 깎이는 두께를 조정해요."},{"ko":"서클 커터","en":"","say":"드릴에 꽂아 원형 구멍을 뚫는 공구","more":"천장 등구멍 타공에 많이 씀."},{"ko":"루터기","en":"","say":"목재 가장자리에 무늬를 넣거나 홈, 경첩자리 홈을 파는 공구","more":"깎는 깊이를 조절하고 여러 날을 골라 써요. 테이블을 쓰면 다량 가공이 돼요."},{"ko":"컴프레셔","en":"","say":"공기압 공구를 돌리는 공기압축기","more":"타카, 에어 스프레이, 에어드릴에 필수."},{"ko":"전동 드릴","en":"","say":"전동모터로 구멍을 뚫거나 나사못 등을 박는 공구","more":"타공용 드릴과 드라이버 드릴이 있어요. 드릴 바이트(드릴 날)는 목재용, 콘크리트용, 철재용."},{"ko":"타카","en":"","say":"공기압으로 핀을 박아 판재를 고정하는 공구","more":"핀은 일 자 핀과 ㄷ 자 핀. 천장 2겹째 석고보드에 ㄷ 자 타카 핀."},{"ko":"먹매김","en":"","say":"설계도서 치수대로 현장에 1:1로 도면을 옮겨 그리는 작업","more":"설계자, 현장소장, 목수가 참여. 설계자는 먹도면을 준비."},{"ko":"양중","en":"","say":"공사에 필요한 자재를 원하는 위치에 적재하는 것","more":"자재관리 순서: 반입, 양중, 저장."},{"ko":"현장소장","en":"","say":"현장을 총괄해 공정, 품질, 안전, 원가, 현장운영을 관리하는 책임자","more":"설계변경은 임의로 하지 않고 발주처, 설계자와 협의."},{"ko":"옹이","en":"","say":"나뭇가지가 붙어 있던 자리가 목재 속에 남은 흔적","more":"목재의 결함 가운데 하나예요. 벽체 틀에는 휨, 비틀림, 심한 옹이 등 결함이 있는 자재를 빼요."},{"ko":"고정목","en":"","say":"목재 벽체 틀에서 바닥과 천장에 수평으로 대는 가로 부재","more":"하부 고정목과 상부 고정목 사이에 세로 목을 세워요. 경량 벽체의 스틸런너와 같은 자리예요."},{"ko":"세로 목","en":"","say":"목재 벽체 틀에서 하부, 상부 고정목 사이에 세우는 세로 부재","more":"간격 300, 450, 600mm 모듈. 필요하면 가로 보강목."},{"ko":"가로 보강목","en":"","say":"필요할 때 세로 목 사이에 가로로 넣어 틀을 튼튼하게 하는 부재","more":"슬라이드는 '필요한 경우' 설치한다고 적어요."},{"ko":"타정핀","en":"","say":"벽체 틀을 콘크리트 같은 바탕에 박아 고정하는 못 모양 철물","more":"벽체 틀 고정철물 3가지 : 타정핀, 콘크리트용 피스, 앵커."},{"ko":"일면 벽체","en":"","say":"기존 벽 앞에 한 겹 틀을 세워 한쪽 면만 마감하는 벽","more":"기존 벽 마감, 설비 공간 확보. 짝은 양면 벽체(공간 구획용 독립 벽)."},{"ko":"양면 벽체","en":"","say":"공간을 나누려고 세우는 독립 벽, 틀 양쪽 면에 판을 붙여요","more":"짝은 일면 벽체(기존 벽 앞 한 겹 틀, 한쪽만 마감)."},{"ko":"방염성능","en":"","say":"불이 잘 붙지 않고 번지지 않게 버티는 성능","more":"목재, 합판에 방염성능이 요구되면 관련 법령과 설계도서가 요구하는 성능에 맞는 자재와 공법을 써요."},{"ko":"석고보드","en":"Gypsum Board","say":"스터드 뼈대 양쪽에 붙이는 판, 벽의 살에 해당","more":"일반적으로 9.5mm나 12.5mm를 2겹으로 시공. 규격은 900 x 1,800, 1,200 x 2,400."},{"ko":"스틸런너","en":"Steel Runner","say":"천장과 바닥면에 고정해 스터드를 고정하는 부재","more":"용융 강판 소재."},{"ko":"달대받이","en":"","say":"달대를 위에서 붙잡아 주도록 보 밑이나 슬라브 밑에 먼저 고정하는 각재","more":"목재 천장은 달대받이 → 달대 → 반자틀받이 → 반자틀 순서로 내려와요. 각재와 합판으로 만든 달대용 패널을 대신 쓰기도 해요."},{"ko":"단열재","en":"INSULATION","say":"EPS, XPS, 글라스울, 미네랄울 등 단열 재료의 총칭","more":"건식벽체는 한쪽 보드를 붙인 뒤 스터드 사이에 단열재를 충진."},{"ko":"2ply","en":"","say":"석고보드를 두 겹 붙이는 것, 투플라이","more":"9.5mm 2겹 양면 벽 두께 103mm, 12.5mm면 115mm. 도면에는 100mm."},{"ko":"코너 비드","en":"Corner Bead","say":"벽체가 직각으로 꺾이는 코너의 파손을 막는 제품"},{"ko":"문선","en":"","say":"문틀 주위 마감이 끝난 뒤 덧붙이는 테두리 마감재","more":"문틀 : X 자 먹매김, 수직, 반드시 보강, 마감 후 문선."},{"ko":"멤브레인","en":"","say":"겉면이 MDF이고 그 위에 필름을 붙인 문짝","more":"입체 디자인 가능. 짝은 ABS 문짝(합성수지, 습기에 강함, 입체 어려움)."},{"ko":"ABS 도어","en":"","say":"겉면을 플라스틱계 합성수지(ABS 수지판)로 덮고 필름으로 마무리한 문짝","more":"속은 허니콤 보드, 테두리는 PVC 심재예요. 변형이 적고 습기에 강하고 가볍지만, 열로 찍어내서 입체 디자인은 어려워요."},{"ko":"조인트 테이프","en":"","say":"석고보드 이음매에 부풀음 없이 붙이는 테이프"},{"ko":"조인트 컴파운드","en":"JOINT COMPOUND","say":"보드 이음매를 메우고 24시간 정도 경화시키는 재료"},{"ko":"반자틀받이","en":"","say":"달대 아래에 고정되어 반자틀을 받쳐 주는 각재","more":"목재 천장 그림에서 달대와 반자틀 사이에 있어요. 시스템 천장의 캐링 채널과 비슷한 자리예요."},{"ko":"M-Bar 클립","en":"","say":"M-Bar를 캐링채널에 고정하는 클립","more":"한쪽 방향으로만 고정하면 뒤틀릴 수 있어 엇갈림 시공."},{"ko":"스프렁 플로어","en":"Sprung Floor","say":"멍에와 장선으로 바닥을 띄운 체육관 탄성바닥 마루","more":"충격 완화와 탄성 확보. 요즘은 금속 시스템 제품."},{"ko":"멍에","en":"","say":"마루 바닥을 띄울 때 아래에서 장선을 받치는 굵은 받침 부재","more":"마루나 무대를 만들 때 멍에와 장선을 먼저 시공해요. 요즘은 금속으로 시스템화된 제품이 많아요."},{"ko":"장선","en":"","say":"멍에 위에 일정 간격으로 걸쳐 마루판을 직접 받치는 부재","more":"멍에와 짝으로 바닥을 띄워 충격을 완화하고 탄성을 확보해요."},{"ko":"셀프레벨링","en":"","say":"유동성 높은 모르타르를 부어 스스로 퍼지게 해 바닥 수평을 맞추는 공법","more":"자동수평몰탈. 미장면이 평활하지 못하면 3mm 합판을 붙이기도 함."},{"ko":"재료분리대","en":"","say":"바닥 재료가 바뀌거나 높이 차이가 나는 경계에 대는 스틸 계열 마감 부재","more":"기존 바닥면과 단차이가 생기는 곳, 연결 자재가 다른 곳을 깔끔하게 마감해요."},{"ko":"상세도","en":"","say":"특정 부위를 어떤 재료와 치수, 순서로 시공할지 보여 주는 도면","more":"상세도를 그린다 = 디테일을 푼다."},{"ko":"비드법 발포 폴리스틸렌","en":"","say":"작은 구슬(비드)을 부풀려 굳힌 스티로폼 계열 판, 온돌 바닥의 맨 아래층","more":"상세도 표기 THK 20~30MM. 층간소음 감소와 바닥 난방을 위해 추가돼요."},{"ko":"경량 기포 콘크리트","en":"","say":"공기 거품을 많이 넣어 가볍게 만든 콘크리트층","more":"상세도 표기 THK 60~100MM. 비드법 발포 폴리스틸렌 위, 시멘트 모르타르 아래에 와요."},{"ko":"엑셀 파이프","en":"","say":"온돌 바닥 모르타르 속에 넣는 온수난방용 관","more":"Ø15mm @200, 고정핀으로 고정. 아래층은 경량 기포 콘크리트 60~100, 비드법 발포 폴리스틸렌 20~30."},{"ko":"허니콤 보드","en":"","say":"두꺼운 종이를 벌집 모양으로 가공한 문짝 심재","more":"테두리 PVC 심재, 겉면 ABS 수지판과 필름 = ABS 도어. 습기에 강하고 가벼움."},{"ko":"C-스터드","en":"C-Stud","say":"가장 일반적인 스터드, 주로 65mm를 450mm 간격으로 설치","more":"300 또는 450mm 간격. 길이 2,400~5,000mm 비규격이라 천장고 실측 후 발주."},{"ko":"올퍼티","en":"","say":"2차로 도장면 전체를 균질하게 하고 발색력을 높이는 퍼티"}],"5":[{"ko":"도장공사","en":"","say":"물체 표면에 도장재료로 도막(도막층)을 만드는 작업을 통틀어 부르는 말","more":"목적은 물체 보호(내습, 내식, 내약품성) + 미적 효과(색채, 광택, 평활성) → 재료 가치 향상. 물품의 최종 마감."},{"ko":"도료","en":"","say":"물체 표면에 발라 굳으면 막이 되는 액상 또는 분말 재료, 흔히 페인트","more":"구성: 전색제 + 안료. 전색제 = 수지 + 용제 + 보조제."},{"ko":"도막","en":"","say":"도료가 마르면서 물체 표면에 생기는 얇은 피막","more":"도장공사 = 도료로 도막 또는 도막층을 형성하는 작업."},{"ko":"피도물","en":"","say":"도장을 하는 대상 물체, 칠을 받는 물건","more":"피도물에 도막을 입혀 보호하고 미적 효과를 줘요. 칠할 면은 피도면."},{"ko":"전색제","en":"vehicle","say":"안료를 분산, 운반하고 도막을 만드는 도료의 액상 성분","more":"수지 + 용제 + 보조제를 통틀어 부름. 안료는 전색제에 들어가지 않아요. 작업성, 부착성, 도막 형성에 관여."},{"ko":"안료","en":"pigment","say":"도막에 색상과 은폐력을 주는 성분","more":"내광성(자외선에 색, 성질이 잘 안 변함), 내후성(햇빛, 비, 온도, 습도에 견딤)에도 영향. 색 안료 외에 방청안료(부식 억제), 방오안료(해양생물 부착 억제)."},{"ko":"수지","en":"resin","say":"도료의 물성을 좌우해 도막 성능의 대부분을 정하는 성분","more":"천연수지(소나무 진액 등)와 합성수지(에폭시 레진, 아크릴 레진 등). 경도, 접착성, 내수성, 내후성, 내약품성이 수지 종류로 달라짐."},{"ko":"용제","en":"solvent","say":"도료를 칠하기 알맞은 점성과 농도로 맞추는 묽힘 재료","more":"칠한 뒤 휘발돼서 도막에 남지 않지만 도막 성능에 영향. 점도와 건조 속도 조절."},{"ko":"보조제","en":"","say":"소량만 넣어 도료의 물성을 높이는 재료, 첨가제","more":"소포제, 건조제, 산화방지제, 분산제, 침전 방지제, 색분리방지재 등."},{"ko":"은폐력","en":"","say":"도막이 밑바탕을 가려 보이지 않게 하는 힘","more":"안료가 색채와 함께 부여하는 성질."},{"ko":"방청안료","en":"","say":"금속의 부식(녹)을 억제하는 안료","more":"광명단(사산화삼납)이 전통적인 방청안료."},{"ko":"방오안료","en":"antifouling","say":"선박, 해양구조물에 따개비 같은 해양생물이 붙는 것을 막는 안료","more":"방오(防汚) = 오염 방지. 방청안료(녹)와 짝으로 헷갈리기 쉬워요."},{"ko":"소포제","en":"","say":"도료 속이나 도막 표면의 기포를 없애는 첨가제","more":"핀홀, 기포 자국 같은 도장 결함을 줄여요. 분산제는 입자가 뭉치지 않게 하는 첨가제."},{"ko":"수성 페인트","en":"water-based paint","say":"물을 주된 희석제로 쓰는 도료","more":"아크릴 수지 등 합성수지가 결합재. 냄새 적고 작업성 좋고 건조 빠름. 실내 벽, 천장에 널리 사용."},{"ko":"발수성 수성 페인트","en":"","say":"콘크리트, 모르타르, PC 외부 마감에 빗물 침투를 막는 수성도료","more":"외부 마감용. 오염제거 기능 수성 페인트는 병원, 학교 등 청소가 잦은 공간용."},{"ko":"비닐 페인트","en":"","say":"비닐계 에멀션 수지가 주성분인 수성도료, 현장 이름 VP도장","more":"평활성이 좋고 도장면이 매끄러워 실내 벽, 천장 마감에 사용. 시공 9단계는 석고보드 면 정리부터."},{"ko":"광도","en":"","say":"도장면이 반짝이는 정도, 무광부터 유광까지","more":"슬라이드 표: 무광 ~5%, 벨벳광 5~9%, 계란광 10~15%, 저광 20~25%, 반광 40~50%, 유광 70~80%."},{"ko":"에그쉘 광","en":"eggshell","say":"계란 껍질 정도의 은은한 광택","more":"홈 인테리어용 페인트에서 가장 많이 쓰는 광도. p42는 '저광 정도', p5 표는 계란광(반무광) 10~15%로 따로 적음."},{"ko":"유성 페인트","en":"oil-based paint","say":"건성유, 알키드수지 등 유성 결합재에 유기용제(신너)를 섞어 쓰는 도료","more":"단단하고 치밀한 도막, 내수성, 내후성, 내마모성 우수. 대신 냄새와 VOC가 많고 건조가 느림. 두껍게 칠하면 흐름, 처짐."},{"ko":"퍼티","en":"putty","say":"바탕면의 요철, 흠집, 균열, 접합부를 메워 평평하게 만드는 재료","more":"현장 말 '빠데'. 접착력이 좋고 경화 후 연마가 잘돼야 함. 주재 + 경화제를 섞으면 2액형 퍼티."},{"ko":"2액형 퍼티","en":"","say":"주재와 경화제를 섞어 쓰는 퍼티","more":"폴리에스테르 퍼티, 에폭시 퍼티가 2액형. 수성 탄성 퍼티(마른 뒤에도 탄성 유지, 미세 균열 보수)는 1액형."},{"ko":"폴리에스테르 퍼티","en":"","say":"금속, 목재 표면 보수와 형상 수정에 쓰는 2액형 퍼티, 현장 말 포리빠데","more":"경화가 빠르고 단단하며 연마성이 좋음. 철재면 위 컬러 도장 3단계에 사용."},{"ko":"에폭시 퍼티","en":"","say":"에폭시수지가 주재인 2액형 퍼티","more":"경화수축이 적고 접착력, 내구성 우수. 바닥, 벽 결손부와 균열, 구조물 보수, 접착에 사용."},{"ko":"바니쉬","en":"varnish","say":"목재의 무늬와 질감을 살리며 표면을 보호하는 투명 도료","more":"투명 도막을 형성. 여러 번 얇게 칠하고 사이사이 건조, 연마. 바니쉬칠 순서: 바탕손질 → 눈먹임 → 착색 → 초벌칠 → 정벌칠 → 닦기, 마무리."},{"ko":"스테인","en":"stain","say":"목재 무늬를 그대로 보이게 하면서 색만 입히는 착색재","more":"덮지 않고 침투하거나 얇게 착색. 표면 보호 성능이 제한적이라 바니쉬, 우레탄, 래커 등 투명 마감재를 추가로 칠함."},{"ko":"실러","en":"sealer","say":"바탕면의 흡수성을 조절하고 윗칠의 부착성을 높이는 하도용 도료","more":"슬라이드 표기 '실라 / 실러'. 콘크리트, 모르타르용 실러, 목재용 샌딩실러. 쵸킹이 생긴 구도막에도 사용."},{"ko":"쵸킹","en":"","say":"도막 표면을 문지르면 가루가 묻어 나오는 현상","more":"수성페인트가 풍화로 깎여 나가고 안료 성분만 남는 현상. 실러로 표면을 안정시킴."},{"ko":"하도","en":"","say":"가장 먼저 하는 기초 칠, 맨 아래 층","more":"주로 젯소, 프라이머, 퍼티 작업. 순서: 하도 → 중도(페인트칠) → 상도(마감, 유지관리, 코팅)."},{"ko":"중도","en":"","say":"하도 위에 올리는 가운데 칠, 페인트칠 층","more":"수성페인트 공정 7단계가 롤러로 하는 중도 작업."},{"ko":"상도","en":"","say":"맨 위에 올리는 마감 칠, 코팅 층","more":"마감 및 유지관리, 코팅 작업. 다채무늬 도료의 상도는 주로 스프레이."},{"ko":"내열도료","en":"","say":"도료 자체가 높은 온도에 견디도록 만든 도료","more":"실리콘수지 결합재, 알루미늄 등 내열 안료. 보일러, 난방기기, 배관, 굴뚝, 배기설비에 사용. 내화도료와 구별."},{"ko":"천연, 친환경 페인트","en":"","say":"자연 유래 원료를 쓰거나 VOC, 중금속 같은 유해물질을 줄인 도료","more":"네추럴 천연 수성도료, 천연 스테인(아이들 가구), 내, 외부용 천연 퍼티(황토, 점토), 세라믹 수성도료."},{"ko":"세라믹 수성도료","en":"","say":"무기질 원료를 주원료로 한 세라믹계 수성도료","more":"난연성, 내구성, 제품에 따라 항균, 항곰팡이. 분말형은 현장에서 물과 혼합."},{"ko":"내화도료","en":"fire-proof paint","say":"불이 났을 때 철골 같은 구조재의 온도 상승을 늦춰 구조물을 지키는 도료","more":"고온에서 도막이 발포, 팽창해 단열 탄화층 형성. 철골 기둥, 보에 사용. 층 순서: 철골 → 하도(방청) → 중도(내화) → 상도(마감)."},{"ko":"방염도료","en":"fire resisting paint","say":"합판, 목재 같은 가연성 재료에 칠해 불붙음과 불길 확산을 늦추는 도료","more":"소방시설 설치 및 관리에 관한 법률의 방염성능기준에 적합해야 함. 잔염 10초, 잔신 30초, 탄화면적 50㎠, 탄화길이 20cm 이내."},{"ko":"잔염시간","en":"","say":"버너 불꽃을 뗀 뒤에도 불꽃을 내며 계속 타는 시간","more":"방염성능기준 10초 이내."},{"ko":"잔신시간","en":"","say":"불꽃은 없지만 붉게 타거나 연소가 계속되는 시간","more":"방염성능기준 30초 이내. (슬라이드 표기 그대로)"},{"ko":"탄화면적","en":"","say":"시험 후 불에 타서 숯이 된 면적","more":"방염성능기준 50㎠ 이내. 탄화길이(탄화된 부분의 최대 길이)는 20cm 이내."},{"ko":"방청도료","en":"rust resisting paint","say":"철재에 칠해 수분과 산소를 막고 부식을 억제하는 하도용 도료","more":"철골, 철문, 난간, 금속 프레임에 사용. 칠 전에 녹, 기름, 먼지, 용접슬래그(현장 말 용접똥) 제거. 광명단, 징크 프라이머, 속건 방청 프라이머."},{"ko":"광명단","en":"red lead","say":"사산화삼납(Pb₃O₄)으로 만든 적갈색, 오렌지색 방청 하도","more":"현장 말 '광명단 칠'. 철재 바탕에 칠하는 대표 방청제(문제풀이: 방청제 ↔ 광명단)."},{"ko":"징크 프라이머","en":"Zinc Primer","say":"아연을 함유한 방청 프라이머","more":"아연 함량이 높은 징크리치 프라이머는 희생방식 작용으로 부식 방지. 철재와 아연도금 부위 보수."},{"ko":"속건 방청 프라이머","en":"","say":"건조 시간을 줄여 다음 칠을 빨리 할 수 있게 한 방청 하도","more":"재도장 가능 시간은 제품마다 달라 제조사 시방을 따름."},{"ko":"다채무늬 도료","en":"multi color paint","say":"여러 색 알갱이가 섞여 한 번에 점박이 무늬를 내는 도료","more":"하도는 붓, 롤러, 상도는 스프레이. 아파트 공용 복도, 오염이 잘 안 보임. 기계로 섞으면 입자가 부서져 손으로 저음."},{"ko":"본타일","en":"","say":"스프레이로 요철이 있는 입체 무늬를 만드는 장식용 도료","more":"입체 무늬 도료. 순서: 하도(프라이머) → 무늬형성도료 → 상도(아크릴계 등). 건물 내부 벽체에 주로 시공."},{"ko":"결로 방지 도료","en":"","say":"실내외 온도 차로 벽, 천장에 생기는 결로를 줄이는 도료","more":"단열성, 흡습성 이용, 항균, 항곰팡이. 아파트, 지하공간, 욕실 주변."},{"ko":"탄성코트","en":"","say":"탄성수지로 도막에 신축성을 준 기능성 도료","more":"미세 균열에 강함. 베란다, 발코니 콘크리트 벽. 수분이 못 빠지면 부풀음, 박리, 터짐 하자."},{"ko":"바이오 세라믹 코트","en":"","say":"세라믹, 광물질 미세 입자가 든 다공성 기능성 도료","more":"수증기가 통과해 바탕 수분 배출을 도움. 규조토 제품은 흡, 방습 강화. 탄성코트와 짝."},{"ko":"경량철골","en":"","say":"목재 대신 철재로 벽틀과 천장틀을 짜는 소재 또는 제품","more":"장점: 불연, 자중 감소, 공기 단축, 내화와 차음 성능 구현, 설비 설치 간단."},{"ko":"석고보드","en":"Gypsum Board","say":"스터드 뼈대 양쪽에 붙이는 판, 벽의 살에 해당","more":"일반적으로 9.5mm나 12.5mm를 2겹으로 시공. 규격은 900 x 1,800, 1,200 x 2,400."},{"ko":"건조분무","en":"dry spray","say":"도료 입자가 칠할 면에 닿기 전에 말라 거칠게 마감되는 현상","more":"강풍, 부적절한 분사거리나 공기압에서 발생. 에어 스프레이에서 '드라이 스프레이' 로도 나옴."},{"ko":"분체도장","en":"","say":"가루 도료를 금속 표면에 정전기로 붙인 뒤 가열해 도막을 만드는 도장","more":"도장 방법에 따른 분류(붓, 롤러, 분무, 정전, 분체)의 하나."},{"ko":"소부건조","en":"","say":"칠한 재료를 가열로에서 구워 도막을 빠르고 단단하게 굳히는 건조","more":"건조, 경화 방법 분류: 자연건조, 강제건조, 소부건조."},{"ko":"폼브러시","en":"foam brush","say":"스펀지로 된 붓, 붓 자국 없이 매끄럽게 칠하는 공구","more":"수성, 유성 도료와 바니쉬에 사용. 붓은 천연모(유성, 바니쉬)와 합성모(수성)."},{"ko":"롤러 브러쉬","en":"","say":"원통 롤러를 굴려 넓은 면을 빠르고 균일하게 칠하는 공구","more":"벽, 천장 같은 넓은 면. 롤러 털 길이와 재질로 도막 두께와 질감이 달라짐."},{"ko":"정판","en":"","say":"퍼티나 컴파운드를 덜어 놓고 섞는 받침판, 퍼티판","more":"목재, 금속, 플라스틱 재질. 주걱(헤라)과 짝."},{"ko":"주걱","en":"spatula","say":"퍼티를 바탕면에 바르고 메우거나 평평하게 펴는 공구, 헤라","more":"금속, 플라스틱, 고무 재질. 주걱 도장의 대표는 안티스터코 도장."},{"ko":"스프레이 건","en":"spray gun","say":"도료를 미세한 입자로 뿜어 칠하는 공구","more":"넓은 면을 균일하고 매끄럽게. 미세 마감은 작은 노즐 구경, 고점도나 하도는 큰 구경."},{"ko":"에어 스프레이","en":"","say":"압축공기로 도료를 잘게 쪼개 뿜는 방식","more":"마감이 섬세하지만 비산이 많아 재료 손실이 큼. 드라이 스프레이 주의. 뿜칠이라고도 하며 외벽은 대기환경 오염으로 금지."},{"ko":"에어리스 스프레이","en":"","say":"공기 없이 도료 자체에 고압을 걸어 뿜는 방식","more":"고점도 도료 가능, 한 번에 많은 양, 넓은 면적을 빠르게. 정밀함보다 생산성."},{"ko":"샌더","en":"sander","say":"샌드페이퍼를 전동으로 움직여 도장면을 평평하게 가는 공구","more":"초벌 퍼티나 중벌 칠 뒤 면 갈이. 폴리셔와 짝."},{"ko":"폴리셔","en":"polisher","say":"회전 패드로 마감면에 광택을 내고 매끄럽게 다듬는 전동공구","more":"펠트, 양모, 스펀지 연마 패드. 인조 대리석 시공 마무리에도 사용."},{"ko":"서페이서","en":"","say":"미세한 흠집, 샌딩 자국, 요철을 메워 표면을 평활하게 하는 중도용 도료","more":"철재면 위 컬러 도장 5단계, MDF 바탕 도장에 사용."},{"ko":"만능 프라이머","en":"","say":"갈바, 알루미늄, 아연도금강판에 얇게 칠해 다음 도료의 부착성을 높이는 하도제","more":"방청을 위한 도료가 아니에요. 방청 프라이머와 구별."},{"ko":"바탕도장","en":"","say":"최종 칠의 부착성, 평활도, 마감 품질을 높이려고 먼저 하는 밑작업","more":"순서: 오염물 제거 → 결함부 보수 → 퍼티 및 샌딩 → 프라이머 또는 실러 → 상도. 초벌도장(녹 방지, 불순물 제거)과 재벌도장(마무리 칠을 위해 면을 평활하게)으로 나눔."},{"ko":"테이퍼드 보드","en":"Tapered Edge Board","say":"이음부 처리가 쉽도록 가장자리를 얇게 깎은 석고보드","more":"슬라이드 표기 '테파드'. 이음부에 조인트 테이프와 퍼티를 채워도 볼록하지 않음."},{"ko":"조인트 퍼티","en":"","say":"조인트 테이프 위 이음매에 헤라로 바르는 퍼티","more":"타카핀, 나사못 자리도 메움. 조인트퍼티 = 이음부 중심 보수, 올퍼티 = 전체 면 평활화."},{"ko":"폴리퍼티","en":"","say":"고무질 성격이 든 퍼티, 이음매 터짐을 예방","more":"석고보드, 합판, MDF 이음매에 일반 퍼티 대신 사용. 금속 이음매에는 일반퍼티와 폴리퍼티 가능."},{"ko":"보양","en":"","say":"기존 시설이나 완성된 마감재의 파손, 오염을 막는 임시 보호","more":"바닥 타일, 석재 위에는 합판, 도장 때 벽에는 비닐, 코너와 문틀에는 각대."},{"ko":"조인트 테이프","en":"","say":"석고보드 이음매에 부풀음 없이 붙이는 테이프"},{"ko":"줄퍼티","en":"","say":"1차로 석고보드 이음매만 메우는 퍼티"},{"ko":"올퍼티","en":"","say":"2차로 도장면 전체를 균질하게 하고 발색력을 높이는 퍼티"},{"ko":"샌딩","en":"","say":"사포나 샌더로 표면을 갈아 평평하게 고르는 작업","more":"퍼티와 짝으로 반복돼요. 수성페인트 9단계에서 퍼티, 샌딩이 네 번 나와요."},{"ko":"아크릴 페인트","en":"","say":"내오염성과 내수성이 좋아 걸레받이처럼 더러워지기 쉬운 곳에 쓰는 페인트","more":"공정 6단계: 퍼티, 샌딩 → 2차 퍼티, 샌딩 → (하도) → 1회 칠 → 퍼티, 샌딩 → 최종 도장. 내구성이 좋아 오래 유지돼요."},{"ko":"방청 프라이머","en":"","say":"일반 철재에 칠해 녹을 막는 하도용 프라이머","more":"철재면 위 컬러 도장 2단계, 철재면 바탕도장에 써요. 만능 프라이머(부착성용, 방청용 아님)와 구별해요."},{"ko":"용접슬래그","en":"","say":"용접할 때 생겨 금속 표면에 붙는 찌꺼기, 현장 말로 용접똥","more":"방청 도장 1단계와 철재면 바탕도장에서 녹, 유분과 함께 제거해요."},{"ko":"초벌도장","en":"","say":"녹을 방지하거나 불순물을 제거하는 바탕도장","more":"바탕도장을 두 갈래로 나눌 때의 하나. 짝은 재벌도장이에요."},{"ko":"재벌도장","en":"","say":"마무리 칠을 하려고 칠할 면을 평활하게 만드는 바탕도장","more":"짝은 초벌도장(녹 방지, 불순물 제거)이에요."},{"ko":"마스킹","en":"","say":"칠하면 안 되는 곳에 테이프나 종이를 붙여 가리는 일","more":"도장면 샌딩이 끝나면 보양과 함께 해요. 도료가 다른 마감재에 묻거나 번지는 것을 막아요."},{"ko":"잔손보기","en":"","say":"최종 칠 뒤 색, 얼룩, 흐름, 빠진 곳을 찾아 손보는 마무리 작업","more":"붓도장(좁은 면적, 모서리, 몰딩의 세밀한 작업)으로 해요. 도장공사의 마지막 단계."},{"ko":"안티스터코 도장","en":"","say":"올퍼티로 면을 정리한 뒤 주걱으로 도장재를 펴 바르며 패턴을 만드는 마감","more":"주걱에 의한 도장의 대표. 정판에 도장재를 얹어 사용. 영상 제목 표기는 '안티코 스타코'."},{"ko":"칠 견본","en":"","say":"본 칠을 하기 전에 작은 판에 미리 칠해 보는 견본","more":"빛깔과 광택을 확인하고, 변색되지 않게 보존해 둬요. 프랜차이즈 인테리어에서 특히 중요해요."},{"ko":"턴키","en":"Turn-key","say":"모든 것을 조달해 바로 쓸 수 있는 상태로 인도하는 도급 방식","more":"일반적으로 설계와 시공을 함께 발주하는 일괄 입찰의 뜻."},{"ko":"감리자","en":"construction supervisor","say":"설계도서대로 시공되는지 확인하고 지도, 감독하는 사람","more":"인테리어 디자인은 의무 감리제도가 없지만 품질관리를 위해 시행."},{"ko":"일식도급","en":"","say":"공사 전부를 한 도급자에게 일괄로 맡기는 방식","more":"총괄도급. 가장 일반적, 설계는 포함 아님. 공사비 확정, 책임 명료."},{"ko":"분할도급","en":"","say":"공사를 유형별로 세분해 각기 다른 도급자와 계약하는 방식","more":"공종별, 공정별, 공구별로 나눔."},{"ko":"공동도급","en":"","say":"여러 회사가 공동출자해 한 회사처럼 공사를 수급하는 방식","more":"대규모 아파트 공사. 자금 부담과 위험 분담."},{"ko":"직접공사비","en":"","say":"재료비, 노무비, 외주비, 경비처럼 공사에 직접 쓴 비용"},{"ko":"간접공사비","en":"","say":"여러 시공 부분이 공통으로 쓰며 비율로 계산하는 비용","more":"현장관리 인건비, 운반비, 전력, 용수비 등."},{"ko":"순공사비","en":"","say":"직접공사비에 공통 가설비와 간접공사비를 더한 금액","more":"원가 순서: 직접공사비, 순공사비, 공사원가, 총원가, 계약금액."},{"ko":"현장경비","en":"","say":"현장 시공 관리를 위해 쓰는 인건비와 기타 경비","more":"현장관리 인력의 인건비, 통신비, 여비교통비 등. 숙소, 식사, 직원 유류비."},{"ko":"공사원가","en":"","say":"순공사비에 현장경비를 더한 금액"},{"ko":"일반관리비","en":"","say":"본사를 유지하는 데 드는 비용","more":"현장에 들어가는 돈이 아니라 본사 인원 등 기업 경영을 위한 돈이에요. 공사원가에 더하면 총원가예요."},{"ko":"가설공사","en":"","say":"본 공사를 위해 임시로 설치했다가 끝나면 철거하는 공사","more":"설계도에 일반적으로 표시되지 않고 시방서에 간단한 지시만. 현장소장 책임."},{"ko":"비계","en":"","say":"높은 곳의 작업을 위해 설치하는 임시시설물","more":"종류: 강관(단관)비계, 시스템비계, 조립식(이동틀)비계, 말비계."},{"ko":"강관틀비계","en":"","say":"강관으로 만든 틀을 실내에서 간단히 조립해 쓰는 비계","more":"중요부품 3가지는 수평틀, 세로틀, 교차가세예요."},{"ko":"조립식 비계","en":"","say":"공장에서 만든 틀과 부품을 현장에서 조립해 바퀴로 밀고 다니는 비계","more":"이동 틀비계라고도 해요. 고정비계를 설치할 수 없는 경우와 단기간 공사에 사용."},{"ko":"가새","en":"","say":"비계가 흔들리지 않게 비스듬히 대는 빗장 부재","more":"슬라이드 그림에서는 40도에서 60도 방향으로 설치하고 기둥에 결속한다고 적혀 있어요."},{"ko":"강관비계","en":"","say":"외경 약 48.6mm 강관을 클램프로 연결해 세우는 비계","more":"단관비계. 설치 숙련도와 안전관리가 중요. 기둥간격 띠장방향 1.85m, 장선방향 1.5m 이하."},{"ko":"띠장","en":"","say":"비계를 앞에서 봤을 때 긴 가로 방향으로 걸리는 수평 부재","more":"띠장방향은 앞에서 본 긴 가로 방향, 띠장간격은 그 가로 부재 사이의 높이예요."},{"ko":"장선","en":"","say":"비계를 옆에서 봤을 때 두께 방향으로 걸리는 수평 부재","more":"장선방향 기둥 간격은 1.5m 이하예요."},{"ko":"쌍줄비계","en":"","say":"건물 주위에 2겹으로 세운 비계","more":"두 겹 사이 이격거리 0.9m. 면적 = H × {2(a + b) + 0.9 × 8} = H × (건물 둘레 + 7.2). 단위 ㎡, 1,000 단위 콤마."},{"ko":"이격거리","en":"","say":"쌍줄비계에서 띄워 두는 거리, 0.9m(90cm)","more":"이 0.9m가 8개라서 쌍줄비계 면적 공식에 0.9 x 8 = 7.2 가 들어가요."},{"ko":"평면도","en":"Floor Plan","say":"공간을 위에서 내려다본 모습으로 그린 도면","more":"방의 배치와 가로, 세로 길이, 문과 창의 위치를 읽어요. 실측도 평면도부터 시작해요."},{"ko":"인서트","en":"","say":"볼트를 달려고 미리 콘크리트에 매입해 둔 철물"},{"ko":"달대 볼트","en":"hanger bolt","say":"달대로 쓰는 직경 9mm 이상의 전산볼트 형태 부재","more":"행거볼트. 약 900mm 간격. 상부는 스트롱 앵커나 인서트, 하부는 행거 클립으로 고정."},{"ko":"행거 클립","en":"","say":"행거볼트와 캐링채널을 고정하는 부속"},{"ko":"캐링 채널","en":"carrying channel","say":"행거에 약 900mm 간격으로 거는 천장틀의 주 골조","more":"천장 하중을 행거를 통해 구조체로 전달. 벽에서 50mm 이하, 엇갈리게 시공, 연결 시 조인트 사용."},{"ko":"마이너 채널","en":"Minor Channel","say":"캐링 채널과 직교해 약 3,000mm 간격으로 거는 보강 채널","more":"시공 그림 기준 2,000~3,000mm."},{"ko":"M-Bar 클립","en":"","say":"M-Bar를 캐링채널에 고정하는 클립","more":"한쪽 방향으로만 고정하면 뒤틀릴 수 있어 엇갈림 시공."},{"ko":"M-Bar","en":"","say":"캐링 채널 아래 300mm 간격으로 걸고 보드를 나사로 박는 폐쇄형 천장틀","more":"가장 기본, 가장 많이 씀. 순서: 앵커, 테두리 몰딩, 행거, 캐링, 마이너, M-Bar, 수평, 1ply, 2ply. 타카 사용 금지."},{"ko":"T-Bar","en":"","say":"격자형 T자 틀 날개 위에 규격 패널을 얹는 탈착형 천장틀","more":"패널을 들어 올려 점검할 수 있어 점검구를 최소화."},{"ko":"코너 비드","en":"Corner Bead","say":"벽체가 직각으로 꺾이는 코너의 파손을 막는 제품"},{"ko":"목공사","en":"","say":"목재를 말리고 다듬고 조립해 틀과 마감을 만드는 공사","more":"순서는 건조처리 → 먹매김 → 마름질 → 바심질 → 세우기예요."},{"ko":"인공 건조","en":"","say":"건조실의 온도, 습도, 풍속을 조절해 말리는 방법","more":"낮은 함수율까지 가능, 자연 조건 영향 없음, 설치비와 유지비 높음, 체적 감소와 균열."},{"ko":"훈연법","en":"","say":"연소 가마에서 나무 부스러기, 톱밥을 태운 연기와 열로 목재를 말리는 방법","more":"목재의 수액 제거 및 건조를 위한 방법이에요."},{"ko":"먹매김","en":"","say":"설계도서 치수대로 현장에 1:1로 도면을 옮겨 그리는 작업","more":"설계자, 현장소장, 목수가 참여. 설계자는 먹도면을 준비."},{"ko":"마름질","en":"","say":"먹매김한 선을 따라 목재를 자르는 일","more":"목공사 순서에서 먹매김(표시하고) 다음, 바심질(뚫어서) 앞이에요."},{"ko":"바심질","en":"","say":"자른 목재에 구멍을 뚫는 등 조립할 자리를 가공하는 일","more":"목공사 순서에서 마름질(자르고) 다음, 세우기(조립) 앞이에요."},{"ko":"구조재","en":"","say":"벽틀, 칸막이 틀처럼 힘을 받는 뼈대에 쓰는 목재","more":"강도가 크고 곧고 길며, 변형이 적고, 충해에 강해야 해요. 적정 함수율 20%."},{"ko":"수장재","en":"","say":"실내 마감 목공사(수장 공사)에 쓰는 목재","more":"재료 자체가 마감이 되므로 무늬가 고르고 옹이 같은 흠이 없어야 해요. 적정 함수율 15%."},{"ko":"옹이","en":"","say":"나뭇가지가 붙어 있던 자리가 목재 속에 남은 흔적","more":"목재의 결함 가운데 하나예요. 수장재는 옹이 등 흠이 없어야 해요."},{"ko":"섬유방향","en":"","say":"나무 섬유가 길게 뻗은 방향, 결방향","more":"섬유방향 인장강도가 가장 크고, 섬유직각방향 인장강도가 가장 작아요."},{"ko":"함수율","en":"","say":"목재가 물을 머금은 정도","more":"낮을수록 강도가 큼. 공식 (건조 전 중량 - 절건 중량) / 절건 중량 × 100. 예제 15kg, 전건 10.8kg이면 38.89%."},{"ko":"MDF","en":"Medium Density Fiber Board","say":"나무를 톱밥처럼 부숴 합성수지로 굳힌 중밀도 섬유판","more":"방향성 없음, 가공성 좋음. 수축되기 쉽고 습기에 약하며 합판보다 약함. 1,220×2,440, 3~30mm, 18T 주로 사용. 도장은 프라이머 필수."},{"ko":"집성목","en":"Glue-Laminated Timber","say":"각재를 섬유방향 평행하게 접착해 모은 목재","more":"변형 적고 긴 장척재. 구조용 집성목, 수장용 집성목. 합판은 직교, 집성목은 평행."},{"ko":"곧은결","en":"","say":"나이테에 직각방향으로 켠 면에 나타나는 평행선 나뭇결","more":"수축, 변형, 마모 적음. 창호재, 장식재, 가구재."},{"ko":"널결","en":"","say":"나이테에 평행방향으로 켠 면에 나타나는 물결 모양 나뭇결","more":"결이 거칠고 불규칙, 변형과 마모 큼. 주로 장식재."},{"ko":"고름질","en":"","say":"바탕의 울퉁불퉁한 곳을 고르게 다듬는 일","more":"일반 도장 순서의 맨 앞, 퍼티와 함께 해요."},{"ko":"초벌칠","en":"","say":"바탕 위에 맨 처음 올리는 첫 칠","more":"일반 도장 순서: 고름질 및 퍼티 → 연마 → 초벌칠 → 중벌칠 → 정벌칠 → 왁스먹임."},{"ko":"중벌칠","en":"","say":"초벌칠 위에 두 번째로 올리는 가운데 칠"},{"ko":"정벌칠","en":"","say":"맨 마지막에 올리는 마감 칠","more":"일반 도장에서는 정벌칠 뒤에 왁스먹임, 바니쉬칠에서는 정벌칠 뒤에 닦기, 마무리예요."},{"ko":"왁스먹임","en":"","say":"다 칠한 뒤 왁스를 발라 윤을 내고 보호하는 마무리"},{"ko":"내알칼리 페인트","en":"","say":"콘크리트, 시멘트, 모르타르 같은 알칼리성 바탕에 칠해도 변색, 박리, 백화가 없는 페인트","more":"문제풀이: 철재 바탕에는 내알칼리 페인트가 아니라 광명단을 도포."},{"ko":"방청제","en":"","say":"금속에 녹이 슬지 않게 막는 재료","more":"문제풀이 짝: 방청제 - 광명단."},{"ko":"방부제","en":"","say":"목재 같은 재료가 썩지 않게 막는 재료","more":"문제풀이 짝: 방부제 - 크레오소트."},{"ko":"착색제","en":"","say":"재료에 색을 입히는 재료","more":"문제풀이 짝: 착색제 - 오일스테인."},{"ko":"희석제","en":"","say":"도료를 묽게 만들어 칠하기 알맞게 하는 재료","more":"문제풀이 짝: 희석제 - 신너."},{"ko":"신너","en":"","say":"유성 도료를 묽게 하는 대표적인 희석제","more":"유성 페인트는 유기용제(신너)를 섞어 써요."},{"ko":"크레오소트","en":"","say":"목재가 썩지 않게 바르는 방부제의 하나","more":"문제풀이에서 방부제와 짝지어요."},{"ko":"오일스테인","en":"","say":"목재에 스며들어 색을 입히는 기름 성분의 착색제","more":"스테인은 나뭇결을 그대로 보이게 하면서 색만 입혀요."},{"ko":"눈먹임","en":"","say":"목재 표면의 작은 구멍(나뭇결 틈)을 메우는 작업","more":"바니쉬칠 2단계: 바탕손질 → 눈먹임 → 착색 → 초벌칠 → 정벌칠 → 닦기, 마무리."}]};
